/// The binding freezes the project, harness, session-slot value, and fallback render budget at bind.
/// The binding freezes the fallback render budget at bind; transform routes store the durable session in `session`.
/// OpenCode Rust routes bind their durable session directly.
/// The route binding, not a request field, supplies the project because a crafted request could read another project's memories.
#[derive(Debug, Clone, PartialEq)]
pub struct SessionBinding {
    pub project_root: PathBuf,
    /// The project the `kernel.*` routes work against, canonicalized at bind.
    pub(crate) kernel_project: kernel_routes::ProjectBinding,
    pub harness: String,
    pub session: String,
    pub model_key: Option<String>,
    pub config: DaemonConfig,
    /// The binding freezes the fallback history budget in tokens at bind.
    /// The binding does not use a newer harness-resolved value because config can change while the route remains open.
    pub history_budget_tokens: f64,
    pub credential_fingerprints: std::collections::BTreeMap<String, String>,
    /// Read from the host backend once at bind and constant for the route epoch; consumer capability strings never change it.
    pub context_capabilities: context_capabilities::LatchedCapabilities,
}

impl SessionBinding {
    /// An observational binding authorizes and resolves its project like any route and is excluded from every background view; see [`RouteBindings::participating`].
    pub(crate) fn is_observational(&self) -> bool {
        self.harness == OBSERVATIONAL_HARNESS
    }
}

/// The harness whose bindings are observational. `harness` is scoping metadata the client claims on `route.open`, never authority: the value selects observation and grants nothing.
pub const OBSERVATIONAL_HARNESS: &str = "cli";

#[derive(Default)]
pub(crate) struct RouteBindings {
    by_route: HashMap<RouteHandle, (u64, SessionBinding)>,
    next_bind_seq: u64,
}

impl RouteBindings {
    /// Binds `channel`, returning the binding it replaced. A rebind counts as
    /// the newest bind on its root.
    fn insert(&mut self, channel: RouteHandle, binding: SessionBinding) -> Option<SessionBinding> {
        let seq = self.next_bind_seq;
        self.next_bind_seq += 1;
        self.by_route
            .insert(channel, (seq, binding))
            .map(|(_, previous)| previous)
    }

    fn remove(&mut self, channel: &RouteHandle) -> Option<SessionBinding> {
        self.by_route.remove(channel).map(|(_, binding)| binding)
    }

    fn get(&self, channel: &RouteHandle) -> Option<&SessionBinding> {
        self.by_route.get(channel).map(|(_, binding)| binding)
    }

    fn values(&self) -> impl Iterator<Item = &SessionBinding> {
        self.by_route.values().map(|(_, binding)| binding)
    }

    fn clear(&mut self) {
        self.by_route.clear();
    }

    /// The bindings that take part in background work, with the sequence that orders them by insertion time. Observational bindings are excluded here, before any newest-per-root selection, so an observer never replaces an older participating binding, an observer-only root contributes nothing, and closing an observer reveals no binding that was not already selected. This is the only view background work reads: the MemoryReviewer worker's projects, the scheduler's roots and schedules, and the search maintenance roster.
    fn participating(&self) -> impl Iterator<Item = (u64, &SessionBinding)> {
        self.by_route
            .values()
            .filter(|(_, binding)| !binding.is_observational())
            .map(|(seq, binding)| (*seq, binding))
    }

    /// The newest participating binding on `route_root`.
    fn latest_for_root(&self, route_root: &Path) -> Option<(u64, &SessionBinding)> {
        self.participating()
            .filter(|(_, binding)| binding.project_root == route_root)
            .max_by_key(|(seq, _)| *seq)
    }

    /// The project of every bound root, keyed by its scope identifier; roots sharing a project collapse to one entry.
    fn bound_projects(&self) -> Vec<(String, kernel::ProjectScope)> {
        let mut projects: BTreeMap<String, kernel::ProjectScope> = BTreeMap::new();
        for (_, binding) in self.latest_per_root().into_values() {
            projects
                .entry(binding.kernel_project.scope_id())
                .or_insert_with(|| binding.kernel_project.scope().clone());
        }
        projects.into_iter().collect()
    }

    /// The newest participating binding on every root that has one, with the sequence that orders bindings by insertion time.
    pub(crate) fn latest_per_root(&self) -> BTreeMap<&Path, (u64, &SessionBinding)> {
        let mut latest: BTreeMap<&Path, (u64, &SessionBinding)> = BTreeMap::new();
        for (seq, binding) in self.participating() {
            let entry = latest
                .entry(binding.project_root.as_path())
                .or_insert((seq, binding));
            if seq > entry.0 {
                *entry = (seq, binding);
            }
        }
        latest
    }
}

fn apply_claude_code_config_controls(
    request: &mut TransformRequest,
    config: &DaemonConfig,
    serializer_profile: Option<SerializerProfile>,
) {
    if serializer_profile != Some(SerializerProfile::ClaudeCodeAnthropic) {
        return;
    }
    // The daemon freezes the fallback history budget at bind.
    request.auto_search_enabled = config.auto_search.enabled;
    request.auto_search_score_threshold = config.auto_search.score_threshold;
    request.auto_search_min_prompt_chars = config.auto_search.min_prompt_chars;
    request.terse_text_compression_enabled = config.terse_text_compression.enabled;
    request.terse_text_compression_min_chars = config.terse_text_compression.min_size;
    // Thalamus does not send a todowrite verdict, and Claude Code has no native todowrite surface.
    // The transform leaves `None` intact because synthesis treats missing todowrite authority as unavailable.
    // Synthesis treats missing todowrite authority as unavailable rather than manufacturing an unreachable tool call.
    if config.prompt_surface_guidance_override.is_some() {
        request.prompt_surface_guidance_override = config.prompt_surface_guidance_override.clone();
    }
}

/// The handler rejects transform requests when the route is unbound or the request session differs from the channel's bound session; it never defaults a project because that could read another project's store.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BindingError {
    /// The handler rejects transforms when the channel has no `on_bind` binding or has been torn down.
    Unbound,
    /// The request's `session_id` must match the channel's bound session because the daemon controls channel identity.
    SessionMismatch,
}

