fn state_sync_seq_mismatch_error(expected: u64, found: u64) -> PreparedOutcome {
    PreparedOutcome::Error {
        code: "authority_seq_mismatch".to_string(),
        message: json!({
            "code": "authority_seq_mismatch",
            "expected_authority_seq": expected,
            "durable_authority_seq": found,
        })
        .to_string(),
    }
}

fn history_summarizer_history_segment_sync_busy_error(
    phase: HistorySummarizerPhase,
) -> PreparedOutcome {
    PreparedOutcome::Error {
        code: "history_summarizer_history_segment_sync_busy".to_string(),
        message: json!({
            "code": "history_summarizer_history_segment_sync_busy",
            "history_summarizer_phase": phase.as_str(),
            "retryable": true,
        })
        .to_string(),
    }
}

