#[derive(Debug)]
struct PendingStateSyncSeed {
    seed_id: String,
    generation: u64,
    expected_seq: u64,
    total: usize,
    next_index: usize,
    digests: Vec<String>,
    batches: Vec<ModuleStateSyncWire>,
    bytes: usize,
    last_activity: Instant,
}

#[derive(Debug)]
enum StateSyncSeedPhase {
    Idle,
    AwaitingSeed { generation: u64, expected_seq: u64 },
    Collecting(PendingStateSyncSeed),
    Applying { seed_id: String, bytes: usize },
}

#[derive(Debug)]
struct CompletedStateSyncSeed {
    seed_id: String,
    final_digest: String,
    generation: u64,
    expected_seq: u64,
    total: usize,
    result: PreparedOutput,
}

#[derive(Debug)]
struct StateSyncSeedSession {
    phase: StateSyncSeedPhase,
    completed: Option<CompletedStateSyncSeed>,
}

impl Default for StateSyncSeedSession {
    fn default() -> Self {
        Self {
            phase: StateSyncSeedPhase::Idle,
            completed: None,
        }
    }
}

#[derive(Debug)]
struct StateSyncSeedCoordinator {
    sessions: HashMap<String, StateSyncSeedSession>,
    total_staged_bytes: usize,
    pending_seed_count: usize,
    max_staged_bytes: usize,
}

impl Default for StateSyncSeedCoordinator {
    fn default() -> Self {
        Self {
            sessions: HashMap::new(),
            total_staged_bytes: 0,
            pending_seed_count: 0,
            max_staged_bytes: STATE_SYNC_SEED_MAX_STAGED_BYTES,
        }
    }
}

impl StateSyncSeedCoordinator {
    fn phase_bytes(phase: &StateSyncSeedPhase) -> usize {
        match phase {
            StateSyncSeedPhase::Collecting(seed) => seed.bytes,
            StateSyncSeedPhase::Applying { bytes, .. } => *bytes,
            StateSyncSeedPhase::Idle | StateSyncSeedPhase::AwaitingSeed { .. } => 0,
        }
    }

    fn is_pending(phase: &StateSyncSeedPhase) -> bool {
        !matches!(phase, StateSyncSeedPhase::Idle)
    }

    fn discard_pending(&mut self, session_id: &str) {
        let Some(session) = self.sessions.get_mut(session_id) else {
            return;
        };
        if Self::is_pending(&session.phase) {
            self.pending_seed_count = self.pending_seed_count.saturating_sub(1);
            self.total_staged_bytes = self
                .total_staged_bytes
                .saturating_sub(Self::phase_bytes(&session.phase));
            session.phase = StateSyncSeedPhase::Idle;
        }
    }

    fn release_phase(&mut self, phase: &StateSyncSeedPhase) {
        if Self::is_pending(phase) {
            self.pending_seed_count = self.pending_seed_count.saturating_sub(1);
            self.total_staged_bytes = self
                .total_staged_bytes
                .saturating_sub(Self::phase_bytes(phase));
        }
    }

    fn set_phase(&mut self, session_id: &str, phase: StateSyncSeedPhase) {
        self.sessions
            .entry(session_id.to_string())
            .or_default()
            .phase = phase;
    }

    fn evict(&mut self, session_id: &str) {
        self.discard_pending(session_id);
        self.sessions.remove(session_id);
    }

    fn evict_stale_collectors(&mut self, now: Instant) {
        let stale_sessions = self
            .sessions
            .iter()
            .filter_map(|(session_id, session)| {
                let StateSyncSeedPhase::Collecting(seed) = &session.phase else {
                    return None;
                };
                (now.saturating_duration_since(seed.last_activity) >= STATE_SYNC_SEED_COLLECTOR_TTL)
                    .then(|| session_id.clone())
            })
            .collect::<Vec<_>>();
        for session_id in stale_sessions {
            self.evict(&session_id);
        }
    }
}

#[derive(Debug)]
struct PendingTransformPage {
    transform_id: String,
    generation: u64,
    total: usize,
    next_index: usize,
    digests: Vec<String>,
    pages: Vec<Value>,
    bytes: usize,
    queued_at_ms: u64,
    last_activity: Instant,
}

#[derive(Debug)]
enum TransformPagePhase {
    Idle,
    Collecting(PendingTransformPage),
    Applying { transform_id: String, bytes: usize },
}

/// CompletedTransformPage retains a final page response so redrives replay its bytes without transforming twice.
#[derive(Debug)]
struct CompletedTransformPage {
    transform_id: String,
    generation: u64,
    page_total: usize,
    final_digest: String,
    /// See [`transform_page_scalar_digest`].
    scalar_digest: String,
    result: PreparedOutput,
    /// Measured wire length, charged against the coordinator's completed-response budget.
    bytes: usize,
    /// Monotonic completion order; the coordinator evicts the lowest sequence first.
    sequence: u64,
}

#[derive(Debug)]
struct TransformPageSession {
    phase: TransformPagePhase,
    completed: Option<CompletedTransformPage>,
    /// Cleared by a discard during `Applying`, so `finish_apply` retains no response.
    retains_result: bool,
}

impl Default for TransformPageSession {
    fn default() -> Self {
        Self {
            phase: TransformPagePhase::Idle,
            completed: None,
            retains_result: true,
        }
    }
}

impl TransformPageSession {
    fn is_empty(&self) -> bool {
        matches!(self.phase, TransformPagePhase::Idle) && self.completed.is_none()
    }
}

/// A shared coordinator limits every session to one in-flight transform page.
/// Each session has one in-flight attempt, and all senders share one bounded staging budget.
/// Completed responses share a second bounded budget; the oldest completion is evicted first.
#[derive(Debug)]
struct TransformPageCoordinator {
    sessions: HashMap<String, TransformPageSession>,
    total_staged_bytes: usize,
    pending_transform_count: usize,
    max_staged_bytes: usize,
    max_pending_transforms: usize,
    completed_bytes: usize,
    max_completed_bytes: usize,
    next_completed_sequence: u64,
}

impl Default for TransformPageCoordinator {
    fn default() -> Self {
        Self {
            sessions: HashMap::new(),
            total_staged_bytes: 0,
            pending_transform_count: 0,
            max_staged_bytes: TRANSFORM_PAGE_MAX_STAGED_BYTES,
            max_pending_transforms: TRANSFORM_PAGE_MAX_PENDING,
            completed_bytes: 0,
            max_completed_bytes: TRANSFORM_PAGE_COMPLETED_BUDGET_BYTES,
            next_completed_sequence: 0,
        }
    }
}

enum TransformPageStageAction {
    Ack(usize),
    Apply {
        pages: Vec<Value>,
        transform_id: String,
        generation: u64,
        page_total: usize,
        final_digest: String,
        inbound_bytes: usize,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TransformPageStageError {
    AttemptMismatch,
    DigestMismatch,
    OrderMismatch,
    BufferOverflow,
    InProgress,
}

impl TransformPageCoordinator {
    fn phase_bytes(phase: &TransformPagePhase) -> usize {
        match phase {
            TransformPagePhase::Collecting(pending) => pending.bytes,
            TransformPagePhase::Applying { bytes, .. } => *bytes,
            TransformPagePhase::Idle => 0,
        }
    }

    fn is_pending(phase: &TransformPagePhase) -> bool {
        !matches!(phase, TransformPagePhase::Idle)
    }

    fn release_phase(&mut self, phase: &TransformPagePhase) {
        if Self::is_pending(phase) {
            self.pending_transform_count = self.pending_transform_count.saturating_sub(1);
            self.total_staged_bytes = self
                .total_staged_bytes
                .saturating_sub(Self::phase_bytes(phase));
        }
    }

    fn release_completed(&mut self, completed: &CompletedTransformPage) {
        self.completed_bytes = self.completed_bytes.saturating_sub(completed.bytes);
    }

    /// Removes the session entry, releasing its staged phase and retained response. An
    /// `Applying` phase is left in place; only [`Self::release_applying`] ends it, and
    /// `finish_apply` retains no response after a discard during `Applying`.
    fn discard(&mut self, session_id: &str) -> Option<usize> {
        if let Some(session) = self.sessions.get_mut(session_id)
            && matches!(session.phase, TransformPagePhase::Applying { .. })
        {
            let completed = session.completed.take();
            session.retains_result = false;
            if let Some(completed) = completed {
                self.release_completed(&completed);
            }
            return None;
        }
        let session = self.sessions.remove(session_id)?;
        let staged_pages = match &session.phase {
            TransformPagePhase::Collecting(pending) => Some(pending.pages.len()),
            TransformPagePhase::Idle | TransformPagePhase::Applying { .. } => None,
        };
        self.release_phase(&session.phase);
        if let Some(completed) = &session.completed {
            self.release_completed(completed);
        }
        staged_pages
    }

    fn remove_if_empty(&mut self, session_id: &str) {
        if self
            .sessions
            .get(session_id)
            .is_some_and(TransformPageSession::is_empty)
        {
            self.sessions.remove(session_id);
        }
    }

    fn set_phase(&mut self, session_id: &str, phase: TransformPagePhase) {
        self.sessions
            .entry(session_id.to_string())
            .or_default()
            .phase = phase;
    }

    fn take_phase(&mut self, session_id: &str) -> TransformPagePhase {
        self.sessions
            .get_mut(session_id)
            .map(|session| std::mem::replace(&mut session.phase, TransformPagePhase::Idle))
            .unwrap_or(TransformPagePhase::Idle)
    }

    fn session_is_pending(&self, session_id: &str) -> bool {
        self.sessions
            .get(session_id)
            .is_some_and(|session| Self::is_pending(&session.phase))
    }

    /// Evicts the oldest completed responses until `bytes` fits under the completed budget.
    /// Returns false when `bytes` exceeds the whole budget and cannot be retained.
    fn reserve_completed_bytes(&mut self, bytes: usize) -> bool {
        if bytes > self.max_completed_bytes {
            return false;
        }
        while self
            .completed_bytes
            .checked_add(bytes)
            .is_none_or(|total| total > self.max_completed_bytes)
        {
            let oldest = self
                .sessions
                .iter()
                .filter_map(|(session_id, session)| {
                    session
                        .completed
                        .as_ref()
                        .map(|completed| (completed.sequence, session_id.clone()))
                })
                .min()
                .map(|(_, session_id)| session_id);
            let Some(session_id) = oldest else {
                return false;
            };
            if let Some(completed) = self
                .sessions
                .get_mut(&session_id)
                .and_then(|session| session.completed.take())
            {
                self.release_completed(&completed);
            }
            self.remove_if_empty(&session_id);
        }
        true
    }

    /// Ends the `Applying` phase for `transform_id`, releasing its staged bytes.
    ///
    /// A successful `result` replaces the session's retained response under the completed
    /// budget. Responses exceeding the completed budget are not retained; redrives re-apply them.
    /// A phase that no longer names `transform_id` is left untouched.
    #[allow(clippy::too_many_arguments)]
    fn finish_apply(
        &mut self,
        session_id: &str,
        transform_id: String,
        generation: u64,
        page_total: usize,
        final_digest: String,
        scalar_digest: String,
        result: Option<PreparedOutput>,
    ) {
        let retains_result = self
            .sessions
            .get(session_id)
            .is_none_or(|session| session.retains_result);
        if !self.release_applying(session_id, &transform_id) {
            return;
        }
        if let Some(previous) = self
            .sessions
            .get_mut(session_id)
            .and_then(|session| session.completed.take())
        {
            self.release_completed(&previous);
        }
        let measured = result.filter(|_| retains_result).and_then(|result| {
            result
                .measure()
                .ok()
                .map(|output| output.len())
                .map(|bytes| (result, bytes))
        });
        if let Some((result, bytes)) = measured
            && self.reserve_completed_bytes(bytes)
        {
            let sequence = self.next_completed_sequence;
            self.next_completed_sequence += 1;
            self.completed_bytes += bytes;
            self.sessions
                .entry(session_id.to_string())
                .or_default()
                .completed = Some(CompletedTransformPage {
                transform_id,
                generation,
                page_total,
                final_digest,
                scalar_digest,
                result,
                bytes,
                sequence,
            });
        }
        self.remove_if_empty(session_id);
    }

    fn oldest_queued_at_ms(&self) -> Option<u64> {
        self.sessions
            .values()
            .filter_map(|session| {
                let TransformPagePhase::Collecting(pending) = &session.phase else {
                    return None;
                };
                Some(pending.queued_at_ms)
            })
            .min()
    }

    /// A retained response is replayable only while the session has no live attempt; a
    /// collector for the same id means the sender is resubmitting pages, which must re-apply.
    fn completed(&self, session_id: &str, transform_id: &str) -> Option<&CompletedTransformPage> {
        self.sessions
            .get(session_id)
            .filter(|session| !Self::is_pending(&session.phase))
            .and_then(|session| session.completed.as_ref())
            .filter(|completed| completed.transform_id == transform_id)
    }

    /// An obsolete completion or drop guard must not release a newer attempt's staging budget.
    fn release_applying(&mut self, session_id: &str, transform_id: &str) -> bool {
        let released = match self.take_phase(session_id) {
            TransformPagePhase::Applying {
                transform_id: applying_id,
                bytes,
            } if applying_id == transform_id => {
                self.release_phase(&TransformPagePhase::Applying {
                    transform_id: applying_id,
                    bytes,
                });
                true
            }
            current => {
                self.set_phase(session_id, current);
                false
            }
        };
        self.remove_if_empty(session_id);
        released
    }

    /// Idle collecting sessions expire after [`TRANSFORM_PAGE_COLLECTOR_TTL`].
    fn evict_stale_collectors(&mut self, now: Instant) -> Vec<(String, usize)> {
        let stale = self
            .sessions
            .iter()
            .filter_map(|(session_id, session)| {
                let TransformPagePhase::Collecting(pending) = &session.phase else {
                    return None;
                };
                (now.saturating_duration_since(pending.last_activity)
                    >= TRANSFORM_PAGE_COLLECTOR_TTL)
                    .then(|| (session_id.clone(), pending.pages.len()))
            })
            .collect::<Vec<_>>();
        for (session_id, _) in &stale {
            self.discard(session_id);
        }
        stale
    }

    #[allow(clippy::too_many_arguments)]
    fn stage(
        &mut self,
        session_id: &str,
        transform_id: String,
        generation: u64,
        page_index: usize,
        page_total: usize,
        page_digest: String,
        page: Value,
        page_bytes: usize,
        page_complete: bool,
        queued_at_ms: u64,
        now: Instant,
    ) -> Result<TransformPageStageAction, TransformPageStageError> {
        if self.pending_transform_count >= self.max_pending_transforms
            && !self.session_is_pending(session_id)
        {
            return Err(TransformPageStageError::BufferOverflow);
        }
        let phase = self.take_phase(session_id);
        match phase {
            TransformPagePhase::Idle => {
                if page_index != 0 {
                    return Err(TransformPageStageError::AttemptMismatch);
                }
                if page_bytes > self.max_staged_bytes
                    || self
                        .total_staged_bytes
                        .checked_add(page_bytes)
                        .is_none_or(|bytes| bytes > self.max_staged_bytes)
                {
                    return Err(TransformPageStageError::BufferOverflow);
                }
                self.total_staged_bytes += page_bytes;
                self.pending_transform_count += 1;
                if page_complete {
                    self.set_phase(
                        session_id,
                        TransformPagePhase::Applying {
                            transform_id: transform_id.clone(),
                            bytes: page_bytes,
                        },
                    );
                    Ok(TransformPageStageAction::Apply {
                        pages: vec![page],
                        transform_id,
                        generation,
                        page_total,
                        final_digest: page_digest,
                        inbound_bytes: page_bytes,
                    })
                } else {
                    self.set_phase(
                        session_id,
                        TransformPagePhase::Collecting(PendingTransformPage {
                            transform_id,
                            generation,
                            total: page_total,
                            next_index: 1,
                            digests: vec![page_digest],
                            pages: vec![page],
                            bytes: page_bytes,
                            queued_at_ms,
                            last_activity: now,
                        }),
                    );
                    Ok(TransformPageStageAction::Ack(1))
                }
            }
            TransformPagePhase::Applying {
                transform_id: active,
                bytes,
            } => {
                self.set_phase(
                    session_id,
                    TransformPagePhase::Applying {
                        transform_id: active,
                        bytes,
                    },
                );
                Err(TransformPageStageError::InProgress)
            }
            TransformPagePhase::Collecting(mut pending) => {
                if pending.transform_id != transform_id
                    || pending.generation != generation
                    || pending.total != page_total
                {
                    self.release_phase(&TransformPagePhase::Collecting(pending));
                    return Err(TransformPageStageError::AttemptMismatch);
                }
                if page_index < pending.next_index {
                    let matches = pending
                        .digests
                        .get(page_index)
                        .is_some_and(|accepted| accepted == &page_digest);
                    let next_index = pending.next_index;
                    if !matches {
                        self.release_phase(&TransformPagePhase::Collecting(pending));
                        return Err(TransformPageStageError::DigestMismatch);
                    }
                    self.set_phase(session_id, TransformPagePhase::Collecting(pending));
                    return Ok(TransformPageStageAction::Ack(next_index));
                }
                if page_index > pending.next_index {
                    self.release_phase(&TransformPagePhase::Collecting(pending));
                    return Err(TransformPageStageError::OrderMismatch);
                }
                let next_bytes = pending.bytes.checked_add(page_bytes);
                let total_bytes = self.total_staged_bytes.checked_add(page_bytes);
                if next_bytes.is_none_or(|bytes| bytes > self.max_staged_bytes)
                    || total_bytes.is_none_or(|bytes| bytes > self.max_staged_bytes)
                {
                    self.release_phase(&TransformPagePhase::Collecting(pending));
                    return Err(TransformPageStageError::BufferOverflow);
                }
                pending.bytes = next_bytes.unwrap_or(usize::MAX);
                self.total_staged_bytes = total_bytes.unwrap_or(usize::MAX);
                pending.next_index += 1;
                pending.digests.push(page_digest.clone());
                pending.pages.push(page);
                pending.last_activity = now;
                if page_complete {
                    let bytes = pending.bytes;
                    let pages = std::mem::take(&mut pending.pages);
                    let active_id = pending.transform_id.clone();
                    let active_generation = pending.generation;
                    let active_total = pending.total;
                    self.set_phase(
                        session_id,
                        TransformPagePhase::Applying {
                            transform_id: active_id.clone(),
                            bytes,
                        },
                    );
                    Ok(TransformPageStageAction::Apply {
                        pages,
                        transform_id: active_id,
                        generation: active_generation,
                        page_total: active_total,
                        final_digest: page_digest,
                        inbound_bytes: bytes,
                    })
                } else {
                    let next_index = pending.next_index;
                    self.set_phase(session_id, TransformPagePhase::Collecting(pending));
                    Ok(TransformPageStageAction::Ack(next_index))
                }
            }
        }
    }
}

