impl HandlerCore {
    fn store(&self) -> Option<Arc<MemoryStore>> {
        self.store.lock().expect("store slot mutex").clone()
    }

    fn admission(&self) -> TaskAdmission {
        TaskAdmission {
            gate: Arc::clone(&self.spawn_gate),
            cancel: self.cancel.clone(),
            tasks: self.tasks.clone(),
        }
    }

    fn spawn_tracked_task<F, T>(&self, future: F) -> Option<tokio::task::JoinHandle<T>>
    where
        F: Future<Output = T> + Send + 'static,
        T: Send + 'static,
    {
        self.admission().spawn(future)
    }

    fn spawn_module_task<F, T>(&self, future: F) -> Option<tokio::task::JoinHandle<T>>
    where
        F: Future<Output = T> + Send + 'static,
        T: Send + 'static,
    {
        self.spawn_tracked_task(future)
    }

    fn begin_store_open(&self, descriptor: StorageDescriptor) -> Result<(), InitError> {
        if self.cancel.is_cancelled() {
            return Err(InitError("module task admission is closed".to_owned()));
        }
        if self.store().is_some()
            || self
                .store_open
                .phase
                .compare_exchange(
                    STORE_OPEN_IDLE,
                    STORE_OPENING,
                    Ordering::AcqRel,
                    Ordering::Acquire,
                )
                .is_err()
        {
            return Ok(());
        }

        self.store_open
            .active_waiters
            .fetch_add(1, Ordering::AcqRel);
        self.store_open
            .waiter_starts
            .fetch_add(1, Ordering::Relaxed);
        let store = Arc::clone(&self.store);
        let kernel = Arc::clone(&self.kernel);
        let admission = self.admission();
        let task_admission = admission.clone();
        let coordinator = Arc::clone(&self.store_open);
        let task_coordinator = Arc::clone(&coordinator);
        let cancel = self.cancel.clone();
        let store_slot = Arc::clone(&self.store);
        let memory_reviewer_status = Arc::clone(&self.memory_reviewer_status);
        let memory_reviewer_host = self
            .memory_reviewer_host
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        let memory_reviewer_permits = Arc::clone(&self.memory_reviewer_permits);
        let bindings = Arc::clone(&self.bindings);
        let memory_classifier = Arc::clone(&self.memory_classifier);
        let search_lifecycle = Arc::clone(&self.search_lifecycle);
        let local_embeddings = self
            .local_embeddings
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        if admission
            .spawn(async move {
                let _guard = StoreOpenWaiterGuard {
                    coordinator: Arc::clone(&task_coordinator),
                };
                let policy = *task_coordinator
                    .policy
                    .lock()
                    .expect("store open policy mutex");
                // Only SQLite hosts a kernel; the flag is set before the open
                // so health never reads a kernel this deployment lacks as
                // still opening.
                kernel.set_expected(matches!(descriptor.backend, StorageBackend::Sqlite { .. }));
                let opened =
                    Self::run_store_open(store, task_coordinator, &descriptor, cancel.clone())
                        .await;
                // The MemoryReviewer sampler and cleanup start as soon as the store is installed; the Kernel joins its passes only while it is ready.
                if opened && let Some(store) = store_slot.lock().expect("store slot mutex").clone()
                {
                    task_admission.spawn(memory_reviewer::lifecycle::run(
                        Arc::clone(&memory_reviewer_status),
                        store,
                        Arc::clone(&kernel),
                        cancel.clone(),
                    ));
                }
                // The scheduler needs only the memory store; it starts once
                // that store is installed, whatever the kernel does next, and
                // holds the store until shutdown joins it.
                if opened && let Some(store) = store_slot.lock().expect("store slot mutex").clone()
                {
                    let host: Arc<dyn memory_classifier_scheduler::SchedulerHost> =
                        Arc::new(SchedulerBridge {
                            store,
                            bindings: Arc::clone(&bindings),
                            memory_classifier,
                            memory_reviewer_status: Arc::clone(&memory_reviewer_status),
                        });
                    let scheduler = memory_classifier_scheduler::MemoryClassifierScheduler::new(
                        Arc::new(memory_classifier_scheduler::WallClock),
                    );
                    task_admission.spawn(scheduler.run(host, cancel.clone()));
                }
                // SQLite supplies the path that derives the kernel root.
                match (opened, &descriptor.backend) {
                    (true, StorageBackend::Sqlite { path }) => {
                        kernel
                            .open(kernel_routes::kernel_root_for(path), policy, cancel.clone())
                            .await;
                        // `kernel.open` returns on cancellation too; an owner bound then would read records during shutdown for a gate nothing can consult.
                        if !cancel.is_cancelled()
                            && let Some(owner) = Self::open_search_lifecycle(
                                &search_lifecycle,
                                &kernel,
                                local_embeddings,
                                &bindings,
                                path,
                            )
                        {
                            task_admission
                                .spawn(search_lifecycle_owner::run_slices(owner, cancel.clone()));
                        }
                        if kernel.state() == kernel_routes::KernelState::Ready
                            && let Some(host) = memory_reviewer_host
                            && let Some(home) = memory_reviewer::worker::Worker::home_of(path)
                            && let Some(store) =
                                store_slot.lock().expect("store slot mutex").clone()
                        {
                            let kernel_source = Arc::clone(&kernel);
                            let project_store = Arc::clone(&store);
                            let project_bindings = Arc::clone(&bindings);
                            task_admission.spawn(memory_reviewer::worker::run(
                                Arc::new(memory_reviewer::worker::Worker {
                                    host,
                                    home,
                                    store,
                                    kernel: Arc::new(move || {
                                        memory_reviewer::worker::ready_kernel(&kernel_source)
                                    }),
                                    projects: Arc::new(move || {
                                        memory_reviewer::worker::module_projects(
                                            &project_store,
                                            &project_bindings,
                                        )
                                    }),
                                    status: Arc::clone(&memory_reviewer_status),
                                    permits: memory_reviewer_permits,
                                    endpoint: memory_reviewer::model_request::Endpoint::anthropic(),
                                }),
                                cancel.clone(),
                            ));
                        }
                        if kernel.state() == kernel_routes::KernelState::Ready
                            && kernel.background_sampler_enabled()
                        {
                            task_admission.spawn(kernel.run_sampler(cancel));
                        }
                    }
                    (true, StorageBackend::Postgres { .. }) => {
                        kernel.mark_unavailable(kernel_routes::UnavailableKind::Unsupported)
                    }
                    (false, _) => kernel.mark_unavailable(kernel_routes::UnavailableKind::Store),
                }
            })
            .is_none()
        {
            coordinator.phase.store(STORE_OPEN_IDLE, Ordering::Release);
            coordinator.finish_waiter();
            return Err(InitError("module task admission is closed".to_owned()));
        }
        Ok(())
    }

    /// Returns whether the cache store was installed.
    async fn run_store_open(
        store_slot: Arc<Mutex<Option<Arc<MemoryStore>>>>,
        coordinator: Arc<StoreOpenCoordinator>,
        descriptor: &StorageDescriptor,
        cancel: CancellationToken,
    ) -> bool {
        let policy = *coordinator.policy.lock().expect("store open policy mutex");
        let mut last_lease_error = match Self::open_store_once(descriptor).await {
            Ok(opened) => {
                if cancel.is_cancelled() {
                    coordinator.phase.store(STORE_OPEN_IDLE, Ordering::Release);
                    return false;
                }
                *store_slot.lock().expect("store slot mutex") = Some(Arc::new(opened));
                coordinator.phase.store(STORE_OPENED, Ordering::Release);
                return true;
            }
            Err(error) if store_open_error_is_live_lease(&error) => error,
            Err(error) => {
                eprintln!("daemon: store open failed: {error}");
                coordinator.phase.store(STORE_OPEN_IDLE, Ordering::Release);
                return false;
            }
        };

        let started = Instant::now();
        coordinator
            .wait_started_at_ms
            .store(now_ms().max(0) as u64, Ordering::Relaxed);
        coordinator
            .phase
            .store(STORE_OPEN_WAITING, Ordering::Release);
        eprintln!(
            "daemon: storage lease held; waiting up to {}s for predecessor exit",
            STORE_LEASE_WAIT_WINDOW.as_secs()
        );

        let mut backoff = policy.initial_backoff;
        let mut attempt = 0usize;
        loop {
            let elapsed = started.elapsed();
            if cancel.is_cancelled() {
                eprintln!(
                    "daemon: storage lease wait cancelled during shutdown after {:.2}s",
                    elapsed.as_secs_f64()
                );
                coordinator.phase.store(STORE_OPEN_IDLE, Ordering::Release);
                return false;
            }
            if elapsed >= policy.wait_window {
                eprintln!(
                    "daemon: storage lease wait expired after {:.2}s; store open failed: {last_lease_error}",
                    elapsed.as_secs_f64()
                );
                coordinator.phase.store(STORE_OPEN_IDLE, Ordering::Release);
                return false;
            }

            let delay = jittered_store_open_delay(backoff, policy.max_backoff, attempt)
                .min(policy.wait_window.saturating_sub(elapsed));
            tokio::select! {
                _ = cancel.cancelled() => {
                    eprintln!(
                        "daemon: storage lease wait cancelled during shutdown after {:.2}s",
                        started.elapsed().as_secs_f64()
                    );
                    coordinator.phase.store(STORE_OPEN_IDLE, Ordering::Release);
                    return false;
                }
                _ = tokio::time::sleep(delay) => {}
            }
            if cancel.is_cancelled() {
                eprintln!(
                    "daemon: storage lease wait cancelled during shutdown after {:.2}s",
                    started.elapsed().as_secs_f64()
                );
                coordinator.phase.store(STORE_OPEN_IDLE, Ordering::Release);
                return false;
            }
            if started.elapsed() >= policy.wait_window {
                continue;
            }

            match Self::open_store_once(descriptor).await {
                Ok(opened) => {
                    if cancel.is_cancelled() {
                        coordinator.phase.store(STORE_OPEN_IDLE, Ordering::Release);
                        return false;
                    }
                    *store_slot.lock().expect("store slot mutex") = Some(Arc::new(opened));
                    coordinator.phase.store(STORE_OPENED, Ordering::Release);
                    eprintln!(
                        "daemon: storage lease released; store opened after {:.2}s",
                        started.elapsed().as_secs_f64()
                    );
                    return true;
                }
                Err(error) if store_open_error_is_live_lease(&error) => {
                    last_lease_error = error;
                    backoff = backoff.saturating_mul(2).min(policy.max_backoff);
                    attempt = attempt.saturating_add(1);
                }
                Err(error) => {
                    eprintln!(
                        "daemon: storage lease wait ended after {:.2}s; store open failed: {error}",
                        started.elapsed().as_secs_f64()
                    );
                    coordinator.phase.store(STORE_OPEN_IDLE, Ordering::Release);
                    return false;
                }
            }
        }
    }

    /// Binds the lifecycle owner to the store's data home once the kernel is ready and a lane is attached, and returns it only on the first binding so exactly one slice loop runs. Nothing is selected at startup, so admission stays closed until the first slice; a refused admission record is reported now rather than at that slice, while an absent one is the ordinary state of a host without approvals.
    fn open_search_lifecycle(
        slot: &Mutex<Option<Arc<search_lifecycle_owner::SearchLifecycleOwner>>>,
        kernel: &kernel_routes::KernelOpenCoordinator,
        local_embeddings: Option<host_runtime::local_embeddings::LocalEmbeddingsComponent>,
        bindings: &Arc<Mutex<RouteBindings>>,
        sqlite_path: &str,
    ) -> Option<Arc<search_lifecycle_owner::SearchLifecycleOwner>> {
        let Some(home) = sqlite_store_data_home(sqlite_path) else {
            eprintln!("daemon: search stays unavailable: the store path is not under a data home");
            return None;
        };
        let (Ok(kernel), Some(local_embeddings)) = (kernel.kernel_store(), local_embeddings) else {
            return None;
        };
        let mut slot = slot
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if slot.is_some() {
            return None;
        }
        let home = Path::new(home);
        if let Err(refusal) = projection_admission::AdmissionInputs::read(home)
            && !matches!(refusal, projection_admission::InputRefusal::Missing(_))
        {
            eprintln!("daemon: search admission record refused: {refusal}");
        }
        let roster = Arc::clone(bindings);
        let owner = Arc::new(
            search_lifecycle_owner::SearchLifecycleOwner::for_home(home, kernel, local_embeddings)
                .with_roster(Arc::new(move || {
                    roster
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .bound_projects()
                })),
        );
        *slot = Some(Arc::clone(&owner));
        Some(owner)
    }

    fn latch_capabilities(&self, harness: &str) -> context_capabilities::LatchedCapabilities {
        let source = self
            .capability_source
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        context_capabilities::LatchedCapabilities::read(source.as_ref(), harness)
    }

    fn lifecycle_owner(&self) -> Option<Arc<search_lifecycle_owner::SearchLifecycleOwner>> {
        self.search_lifecycle
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
    }

    /// The lifecycle owner, once the kernel is ready under a SQLite store with a lane attached.
    #[cfg(feature = "test-support")]
    pub fn search_lifecycle(&self) -> Option<Arc<search_lifecycle_owner::SearchLifecycleOwner>> {
        self.lifecycle_owner()
    }

    async fn open_store_once(
        descriptor: &StorageDescriptor,
    ) -> Result<MemoryStore, MemoryStoreError> {
        let descriptor = descriptor.clone();
        match tokio::task::spawn_blocking(move || MemoryStore::open(&descriptor)).await {
            Ok(result) => result,
            Err(error) => panic!("store open worker failed: {error}"),
        }
    }

    #[cfg(test)]
    fn set_store_open_policy_for_test(&self, policy: StoreOpenPolicy) {
        *self
            .store_open
            .policy
            .lock()
            .expect("store open policy mutex") = policy;
    }
}

