    fn boundary_snapshot_with_entry(block_id: &str) -> BoundaryTokenCacheSnapshot {
        let mut entry_updates = HashMap::new();
        entry_updates.insert(
            block_id.to_string(),
            BoundaryTokenCacheEntry {
                byte_size: 1,
                content_hash: [0u8; 32],
                token_count: 1,
            },
        );
        BoundaryTokenCacheSnapshot {
            entry_updates,
            ..BoundaryTokenCacheSnapshot::default()
        }
    }

    /// One boundary-token entry's byte charge for an `id_len`-byte block id.
    fn boundary_entry_charge(id_len: usize) -> usize {
        id_len + std::mem::size_of::<BoundaryTokenCacheEntry>() + 64
    }

    #[test]
    fn boundary_token_cache_refuses_an_insert_larger_than_its_budget() {
        let mut cache = BoundaryTokenCache::new(boundary_entry_charge(2) - 1);
        cache.replace("s1", boundary_snapshot_with_entry("b1"));
        assert!(cache.sessions.is_empty());
        assert_eq!(cache.retained_bytes, 0);
        assert!(cache.lru.is_empty());
    }

    struct SettlementWriter {
        events: Arc<Mutex<Vec<&'static str>>>,
        bytes: Vec<u8>,
    }

    impl std::io::Write for SettlementWriter {
        fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
            self.events.lock().unwrap().push("write");
            self.bytes.extend_from_slice(bytes);
            Ok(bytes.len())
        }

        fn flush(&mut self) -> std::io::Result<()> {
            Ok(())
        }
    }

    #[tokio::test]
    async fn production_settlement_reserves_before_write_and_returns_exact_body() {
        let events = Arc::new(Mutex::new(Vec::new()));
        let reserve_events = Arc::clone(&events);
        let settlement = settle_prepared_with(
            PreparedOutcome::Response(PreparedOutput::cached_bytes(b"exact-body".to_vec())),
            || false,
            move |len| {
                reserve_events.lock().unwrap().push("reserve");
                let events = Arc::clone(&reserve_events);
                async move {
                    Ok::<_, ()>(SettlementWriter {
                        events,
                        bytes: Vec::with_capacity(len),
                    })
                }
            },
        )
        .await;
        let PreparedSettlement::Response(writer) = settlement else {
            panic!("successful settlement must return a response");
        };
        assert_eq!(writer.bytes, b"exact-body");
        let events = events.lock().unwrap();
        assert_eq!(events.first(), Some(&"reserve"));
        assert!(events[1..].iter().all(|event| *event == "write"));
    }

    #[tokio::test]
    async fn json_settlement_streams_into_the_reservation_without_a_prior_encoding() {
        let value = serde_json::json!({
            "a": ["one", "two", "three"],
            "b": {"c": 1, "d": 2, "e": [true, false, null]},
            "f": "payload",
        });
        let events = Arc::new(Mutex::new(Vec::new()));
        let reserve_events = Arc::clone(&events);
        let reserved = Arc::new(AtomicUsize::new(0));
        let reserved_len = Arc::clone(&reserved);
        let settlement = settle_prepared_with(
            PreparedOutcome::Response(PreparedOutput::json(value.clone())),
            || false,
            move |len| {
                reserve_events.lock().unwrap().push("reserve");
                reserved_len.store(len, Ordering::SeqCst);
                let events = Arc::clone(&reserve_events);
                async move {
                    Ok::<_, ()>(SettlementWriter {
                        events,
                        bytes: Vec::with_capacity(len),
                    })
                }
            },
        )
        .await;
        let PreparedSettlement::Response(writer) = settlement else {
            panic!("successful settlement must return a response");
        };
        let expected = serde_json::to_vec(&value).expect("value serializes");
        assert_eq!(writer.bytes, expected);
        assert_eq!(reserved.load(Ordering::SeqCst), expected.len());
        let events = events.lock().unwrap();
        assert_eq!(events.first(), Some(&"reserve"));
        let writes = events[1..].len();
        assert!(
            events[1..].iter().all(|event| *event == "write"),
            "every post-reservation event is a write"
        );
        assert!(
            writes > 1,
            "serde streamed into the reservation ({writes} writes); a single \
             write_all would mean a fully encoded body existed before it"
        );
    }

    #[tokio::test]
    async fn production_settlement_error_and_stream_skip_reservation() {
        let reservations = Arc::new(AtomicUsize::new(0));
        for outcome in [
            PreparedOutcome::Error {
                code: "invalid".to_owned(),
                message: "bad".to_owned(),
            },
            PreparedOutcome::Streamed,
        ] {
            let reservations = Arc::clone(&reservations);
            let settlement: PreparedSettlement<Vec<u8>> = settle_prepared_with(
                outcome,
                || false,
                move |_| {
                    reservations.fetch_add(1, Ordering::SeqCst);
                    std::future::ready(Ok(Vec::new()))
                },
            )
            .await;
            assert!(!matches!(settlement, PreparedSettlement::Response(_)));
        }
        assert_eq!(reservations.load(Ordering::SeqCst), 0);
    }

    #[tokio::test]
    async fn production_settlement_cancellation_and_denial_emit_no_body() {
        let reservations = Arc::new(AtomicUsize::new(0));
        let reserve_count = Arc::clone(&reservations);
        let before: PreparedSettlement<Vec<u8>> = settle_prepared_with(
            PreparedOutcome::Response(PreparedOutput::cached_bytes(b"body".to_vec())),
            || true,
            move |_| {
                reserve_count.fetch_add(1, Ordering::SeqCst);
                std::future::ready(Ok(Vec::new()))
            },
        )
        .await;
        assert!(matches!(
            before,
            PreparedSettlement::Error { ref code, .. } if code == "request_cancelled"
        ));
        assert_eq!(reservations.load(Ordering::SeqCst), 0);

        let checks = AtomicUsize::new(0);
        let reserve_count = Arc::clone(&reservations);
        let between: PreparedSettlement<Vec<u8>> = settle_prepared_with(
            PreparedOutcome::Response(PreparedOutput::cached_bytes(b"body".to_vec())),
            || checks.fetch_add(1, Ordering::SeqCst) == 1,
            move |_| {
                reserve_count.fetch_add(1, Ordering::SeqCst);
                std::future::ready(Ok(Vec::new()))
            },
        )
        .await;
        assert!(matches!(
            between,
            PreparedSettlement::Error { ref code, .. } if code == "request_cancelled"
        ));
        assert_eq!(reservations.load(Ordering::SeqCst), 1);

        let denied: PreparedSettlement<Vec<u8>> = settle_prepared_with(
            PreparedOutcome::Response(PreparedOutput::cached_bytes(b"body".to_vec())),
            || false,
            |_| std::future::ready(Err(())),
        )
        .await;
        assert!(matches!(
            denied,
            PreparedSettlement::Error { ref code, .. } if code == "output_unavailable"
        ));
    }

    #[test]
    fn the_trigger_reads_the_schedulers_usage_fallback_and_threshold() {
        let parsed = |body: Value| serde_json::from_value::<TransformRequest>(body).unwrap();
        let base =
            json!({"kind": "transform", "session_id": "s", "render_config": "c", "messages": []});
        let usage = |input: u64, limit: u64| ModuleUsage {
            current_total_input_tokens: input,
            context_limit_tokens: limit,
            ..ModuleUsage::default()
        };
        let persisted = usage(140_000, 200_000);
        // No request usage: the persisted 70% reaches the proactive tier.
        let (_, _, pct) = scheduler_usage_numbers(&parsed(base.clone()), Some(&persisted));
        assert!((pct - 70.0).abs() < 1e-9, "{pct}");
        // Request usage wins over persisted; an all-zero request falls back.
        let mut with_usage = base.clone();
        with_usage["usage"] =
            json!({"current_total_input_tokens": 80_000, "context_limit_tokens": 200_000});
        let (_, _, pct) = scheduler_usage_numbers(&parsed(with_usage), Some(&persisted));
        assert!((pct - 40.0).abs() < 1e-9, "{pct}");
        let mut zero = base.clone();
        zero["usage"] = json!({"current_total_input_tokens": 0, "context_limit_tokens": 0});
        let (_, _, pct) = scheduler_usage_numbers(&parsed(zero), Some(&persisted));
        assert!((pct - 70.0).abs() < 1e-9, "{pct}");
        // Compare scheduler_usage_numbers with the scheduler's resolved usage and limit for every request and persisted-usage combination.
        let mut with_geometry = base.clone();
        with_geometry["geometry"] =
            json!({"usable_soft": 167_000, "usable_hard": 200_000, "derivation": "d"});
        let tiny = usage(50_000, 500);
        for (request, persisted) in [
            (&base, Some(&persisted)),
            (&base, Some(&tiny)),
            (&with_geometry, Some(&tiny)),
            (&with_geometry, Some(&persisted)),
            (&with_geometry, None),
            (&base, None),
        ] {
            let request = parsed(request.clone());
            let scheduler_usage = transform::effective_usage(request.usage.as_ref(), persisted);
            let limit = transform::effective_context_limit_tokens(
                &scheduler_usage,
                request.geometry.as_ref(),
            );
            let input = scheduler_usage.current_total_input_tokens as f64;
            assert_eq!(
                scheduler_usage_numbers(&request, persisted),
                (limit, input, input / limit * 100.0),
                "{persisted:?} {:?}",
                request.geometry
            );
        }

        // Threshold: the request override, else the bound config, resolved and capped as the scheduler resolves it.
        let mut bound = default_test_config();
        bound.execute_threshold_percentage = 70.0;
        assert_eq!(
            scheduler_execute_threshold(&parsed(base.clone()), &bound),
            70.0
        );
        let mut overridden = base.clone();
        overridden["effective_execute_threshold"] = json!(95.0);
        assert_eq!(
            scheduler_execute_threshold(&parsed(overridden), &bound),
            90.0
        );
        bound.execute_threshold_percentage = 97.0;
        assert_eq!(
            scheduler_execute_threshold(&parsed(base.clone()), &bound),
            90.0
        );
    }

    #[test]
    fn usage_numbers_rejects_implausible_context_limit() {
        let tiny = ModuleUsage {
            current_total_input_tokens: 50_000,
            context_limit_tokens: 500,
            final_wire_input_tokens: 0,
            final_wire_trusted: false,
        };
        let (limit, _, pct) = usage_numbers(Some(&tiny), None);
        assert_eq!(limit, 200_000.0);
        assert!((pct - 25.0).abs() < 0.01, "pct={pct}");

        let ok = ModuleUsage {
            current_total_input_tokens: 133_000,
            context_limit_tokens: 167_000,
            final_wire_input_tokens: 0,
            final_wire_trusted: false,
        };
        let (limit, _, pct) = usage_numbers(Some(&ok), None);
        assert_eq!(limit, 167_000.0);
        assert!((pct - 79.64).abs() < 0.1, "pct={pct}");

        let one_m = ModuleUsage {
            current_total_input_tokens: 800_000,
            context_limit_tokens: 1_000_000,
            final_wire_input_tokens: 0,
            final_wire_trusted: false,
        };
        let (limit, _, pct) = usage_numbers(Some(&one_m), None);
        assert_eq!(limit, 1_000_000.0);
        assert!((pct - 80.0).abs() < 0.01, "pct={pct}");
    }

