    fn short_store_open_policy(wait_window: Duration) -> StoreOpenPolicy {
        StoreOpenPolicy {
            wait_window,
            initial_backoff: Duration::from_millis(10),
            max_backoff: Duration::from_millis(20),
        }
    }

    async fn wait_for_store_open_phase(handler: &Handler, phase: u8) {
        tokio::time::timeout(Duration::from_secs(10), async {
            while handler.store_open.phase.load(Ordering::Acquire) != phase {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("store open phase should advance");
    }

    async fn wait_for_store_open(handler: &Handler) {
        tokio::time::timeout(Duration::from_secs(10), async {
            while handler.store().is_none() {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("store should open after the predecessor releases its lease");
    }

    #[tokio::test]
    async fn lease_held_then_freed_opens_store_and_discriminates_requests() {
        let dir = tempfile::tempdir().unwrap();
        let data_home = dir.path().join("data");
        std::fs::create_dir_all(&data_home).unwrap();
        let descriptor = dev_descriptor_at(data_home.to_str().unwrap());
        let predecessor = MemoryStore::open(&descriptor).unwrap();
        let handler = Handler::new();
        // wait.
        handler.set_store_open_policy_for_test(short_store_open_policy(Duration::from_secs(30)));

        handler.begin_store_open(descriptor).unwrap();
        wait_for_store_open_phase(&handler, STORE_OPEN_WAITING).await;
        let before = error_frame(call_transform_outcome(&handler, request(big_messages())).await);
        assert_eq!(before.0, "store_unavailable");
        assert_eq!(before.1, "store not opened (no HELLO_ACK storage seam)");

        drop(predecessor);
        wait_for_store_open(&handler).await;
        let after = error_frame(call_transform_outcome(&handler, request(big_messages())).await);
        assert_eq!(after.0, "route_unbound");
    }

    #[tokio::test]
    async fn lease_held_past_window_preserves_terminal_store_error() {
        let dir = tempfile::tempdir().unwrap();
        let data_home = dir.path().join("data");
        std::fs::create_dir_all(&data_home).unwrap();
        let descriptor = dev_descriptor_at(data_home.to_str().unwrap());
        let _predecessor = MemoryStore::open(&descriptor).unwrap();
        let handler = Handler::new();
        handler.set_store_open_policy_for_test(short_store_open_policy(Duration::from_millis(60)));

        handler.begin_store_open(descriptor).unwrap();
        wait_for_store_open_phase(&handler, STORE_OPEN_WAITING).await;
        let before = error_frame(call_transform_outcome(&handler, request(big_messages())).await);
        wait_for_store_open_phase(&handler, STORE_OPEN_IDLE).await;
        let after = error_frame(call_transform_outcome(&handler, request(big_messages())).await);
        assert_eq!(after, before);
    }

    #[tokio::test]
    async fn double_store_open_during_lease_wait_has_one_waiter() {
        let dir = tempfile::tempdir().unwrap();
        let data_home = dir.path().join("data");
        std::fs::create_dir_all(&data_home).unwrap();
        let descriptor = dev_descriptor_at(data_home.to_str().unwrap());
        let _predecessor = MemoryStore::open(&descriptor).unwrap();
        let handler = Handler::new();
        handler.set_store_open_policy_for_test(short_store_open_policy(Duration::from_millis(500)));

        handler.begin_store_open(descriptor.clone()).unwrap();
        wait_for_store_open_phase(&handler, STORE_OPEN_WAITING).await;
        handler.begin_store_open(descriptor).unwrap();
        tokio::time::sleep(Duration::from_millis(30)).await;

        assert_eq!(handler.store_open.waiter_starts.load(Ordering::Relaxed), 1);
        assert_eq!(handler.store_open.active_waiters.load(Ordering::Relaxed), 1);
    }

    #[tokio::test]
    async fn shutdown_cancels_store_lease_wait_promptly() {
        let dir = tempfile::tempdir().unwrap();
        let data_home = dir.path().join("data");
        std::fs::create_dir_all(&data_home).unwrap();
        let descriptor = dev_descriptor_at(data_home.to_str().unwrap());
        let _predecessor = MemoryStore::open(&descriptor).unwrap();
        let handler = Handler::new();
        handler.set_store_open_policy_for_test(short_store_open_policy(Duration::from_secs(5)));
        let coordinator = Arc::clone(&handler.store_open);

        handler.begin_store_open(descriptor).unwrap();
        wait_for_store_open_phase(&handler, STORE_OPEN_WAITING).await;
        drop(handler);
        tokio::time::timeout(Duration::from_millis(200), async {
            while coordinator.active_waiters.load(Ordering::Acquire) != 0 {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("store lease waiter should stop on handler shutdown");
    }

    #[tokio::test]
    async fn shutdown_cancels_and_joins_tracked_history_summarizer_worker() {
        let handler = Handler::new();
        let observed = Arc::new(AtomicBool::new(false));
        let worker_observed = Arc::clone(&observed);
        let cancel = handler.cancel.clone();
        handler
            .spawn_tracked_task(async move {
                cancel.cancelled().await;
                worker_observed.store(true, Ordering::SeqCst);
            })
            .expect("history_summarizer worker admitted");

        <Handler as CompositeComponent>::shutdown(&handler)
            .await
            .unwrap();

        assert!(observed.load(Ordering::SeqCst));
        assert!(handler.tasks.is_empty());
    }

    /// The tracked task binds the lifecycle owner after cancellation, so the owner exists only once shutdown is already joining its tasks.
    #[tokio::test]
    async fn shutdown_closes_a_lifecycle_owner_bound_during_the_join() {
        use projection_admission::{Closed, Refresh};
        use search_lifecycle_owner::{SearchLifecycleOwner, SliceOutcome};

        let dir = tempfile::tempdir().unwrap();
        let home = dir.path().to_owned();
        let kernel = Arc::new(kernel::KernelStore::open(home.join("kernel")).unwrap());
        let handler = Handler::new();
        let slot = Arc::clone(&handler.search_lifecycle);
        let cancel = handler.cancel.clone();
        let owner = Arc::new(SearchLifecycleOwner::for_home(
            &home,
            kernel,
            host_runtime::local_embeddings::LocalEmbeddingsComponent::unsupported("no lane"),
        ));
        let bound = Arc::clone(&owner);
        handler
            .spawn_tracked_task(async move {
                cancel.cancelled().await;
                *slot.lock().unwrap() = Some(bound);
            })
            .expect("late binder admitted");

        <Handler as CompositeComponent>::shutdown(&handler)
            .await
            .unwrap();

        assert!(
            handler.search_lifecycle().is_none(),
            "a joined owner is released with the store"
        );
        assert_eq!(
            owner.admission().refresh(None),
            Refresh::Closed(Closed::ShutDown),
            "no refresh reopens a gate after shutdown"
        );
        assert!(matches!(
            owner.run_slice(&kernel::applicability::EvalBudget::unbounded()),
            SliceOutcome::Disabled
        ));
        assert!(owner.maintenance().is_none());
    }

    fn handler_with_blocking_lifecycle(
        call: BlockingLifecycleCall,
    ) -> (
        Handler,
        Arc<MemoryStore>,
        Arc<BlockingLifecycleState>,
        tempfile::TempDir,
    ) {
        let state = BlockingLifecycleState::new(call);
        let factory = Arc::new(BlockingLifecycleFactory {
            state: Arc::clone(&state),
        });
        let handler = Handler::with_producer_factory_and_config(factory, default_test_config());
        *state.cancel.lock().unwrap() = Some(handler.cancel.clone());

        let dir = tempfile::tempdir().unwrap();
        let data_home = dir.path().join("data");
        std::fs::create_dir_all(&data_home).unwrap();
        let store =
            Arc::new(MemoryStore::open(&dev_descriptor_at(data_home.to_str().unwrap())).unwrap());
        handler.install_store_for_test(Arc::clone(&store));
        let project = dir.path().join("project");
        std::fs::create_dir_all(&project).unwrap();
        handler.bind_route(test_route(7), binding(project.to_str().unwrap(), "ses"));
        (handler, store, state, dir)
    }

    async fn wait_for_blocking_lifecycle(state: &BlockingLifecycleState) {
        tokio::time::timeout(Duration::from_secs(2), async {
            while !state.entered.load(Ordering::SeqCst) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("history_summarizer call site entered injected blocking future");
    }

    async fn assert_shutdown_joined_lifecycle_task(
        handler: &Handler,
        state: &BlockingLifecycleState,
    ) {
        tokio::time::timeout(
            Duration::from_secs(1),
            <Handler as CompositeComponent>::shutdown(handler),
        )
        .await
        .expect("shutdown must join blocked history_summarizer call site")
        .unwrap();
        assert!(state.exited.load(Ordering::SeqCst));
        assert!(handler.cancel.is_cancelled());
        assert!(handler.tasks.is_empty());
        assert!(handler.spawn_module_task(async {}).is_none());
    }

    #[tokio::test]
    async fn shutdown_cancels_actual_spawned_history_summarizer_start_call_site() {
        let (handler, _store, state, _dir) =
            handler_with_blocking_lifecycle(BlockingLifecycleCall::Start);
        let response = call_transform(&handler, big_messages()).await;
        assert_eq!(response["history_summarizer"]["fired"], true);
        wait_for_blocking_lifecycle(&state).await;
        assert_shutdown_joined_lifecycle_task(&handler, &state).await;
    }

    #[tokio::test]
    async fn shutdown_cancels_actual_spawned_history_summarizer_reattach_call_site() {
        let (handler, store, state, _dir) =
            handler_with_blocking_lifecycle(BlockingLifecycleCall::Reattach);
        let messages = big_messages();
        seed_awaiting(&store, &messages);
        let response = call_transform(&handler, messages).await;
        assert_eq!(response["history_summarizer"]["no_fire"], "reattaching");
        wait_for_blocking_lifecycle(&state).await;
        assert_shutdown_joined_lifecycle_task(&handler, &state).await;
        assert!(handler.reattaching_sessions.lock().unwrap().is_empty());
    }

    #[tokio::test]
    async fn lease_wait_health_detail_advances_elapsed_time() {
        let dir = tempfile::tempdir().unwrap();
        let data_home = dir.path().join("data");
        std::fs::create_dir_all(&data_home).unwrap();
        let descriptor = dev_descriptor_at(data_home.to_str().unwrap());
        let _predecessor = MemoryStore::open(&descriptor).unwrap();
        let handler = Handler::new();
        handler.set_store_open_policy_for_test(short_store_open_policy(Duration::from_millis(500)));

        handler.begin_store_open(descriptor).unwrap();
        wait_for_store_open_phase(&handler, STORE_OPEN_WAITING).await;
        let first = <Handler as CompositeComponent>::health(&handler).await;
        tokio::time::sleep(Duration::from_millis(35)).await;
        let second = <Handler as CompositeComponent>::health(&handler).await;

        assert_eq!(first.status, HealthStatus::Degraded);
        assert_eq!(second.status, HealthStatus::Degraded);
        let first_detail = first.detail.unwrap();
        let second_detail = second.detail.unwrap();
        assert!(first_detail.starts_with("waiting on storage lease, held by prior incarnation, "));
        assert!(second_detail.ends_with("s elapsed"));
        assert_ne!(first_detail, second_detail);
        assert!(
            second.metrics.unwrap()["storage_lease_wait_elapsed_ms"].as_u64()
                > first.metrics.unwrap()["storage_lease_wait_elapsed_ms"].as_u64()
        );
    }

