    #[test]
    fn manifest_declares_module_id_and_tools_without_resolver_consumer() {
        let manifest = manifest("context");
        assert_eq!(manifest.module_id, "context");
        assert_eq!(manifest.provides[0]["role"], "tool_provider");
        assert!(manifest.provides[0].get("consumes").is_none());
        let tools: Vec<prompt_surface::Tool> =
            serde_json::from_value(manifest.provides[0]["tools"].clone()).unwrap();
        assert_eq!(
            tools
                .iter()
                .map(|tool| tool.name.as_str())
                .collect::<Vec<_>>(),
            vec![
                "transform",
                "eidnara_reduce",
                "eidnara_memory",
                "eidnara_search",
                "eidnara_note",
            ]
        );
        let by_name = tools
            .iter()
            .map(|tool| (tool.name.as_str(), tool))
            .collect::<HashMap<_, _>>();
        for name in ["eidnara_memory", "eidnara_search"] {
            let tool = by_name
                .get(name)
                .unwrap_or_else(|| panic!("missing tool {name}"));
            assert_eq!(tool.name, name);
            assert_eq!(tool.schema["type"], "object");
            assert!(tool.schema["properties"].is_object());
            assert!(tool.description.as_deref().is_some_and(|text| {
                !text.contains("Eidnara") && !text.contains("transform") && !text.contains('§')
            }));
        }
        assert_eq!(
            by_name["eidnara_note"].description.as_deref(),
            Some(
                "Save or inspect durable session notes for future follow-ups. No evaluator ships with the plugin: writes and updates that set or change surface_condition are refused unless an external host registered a live evaluator."
            )
        );
        assert_eq!(
            by_name["eidnara_note"].schema["properties"]["surface_condition"]["description"],
            json!(
                "Optional externally checkable condition. Setting or changing it is refused unless a live evaluator is registered."
            )
        );
        assert_eq!(
            by_name["eidnara_memory"].execution_mode,
            prompt_surface::ExecutionMode::Mutating
        );
        assert_eq!(
            by_name["eidnara_search"].execution_mode,
            prompt_surface::ExecutionMode::Pure
        );
    }

