    /// Bodies whose `Value` tree drops a repeated key or collapses a raw-value document.
    const VALUE_STRING_ORACLE_EXCLUDED: &[&str] = &[
        "duplicate top-level key",
        "duplicate discriminator",
        "duplicate nested key",
        "messages as an object",
        "raw-value token holding a document",
    ];

    fn value_string_bytes(value: &Value) -> usize {
        match value {
            Value::String(text) => text.len(),
            Value::Array(items) => items.iter().map(value_string_bytes).sum(),
            Value::Object(map) => map
                .iter()
                .map(|(key, value)| key.len() + value_string_bytes(value))
                .sum(),
            _ => 0,
        }
    }

    /// Every body keeps its unbounded-pool terminal on the lane production selects for it.
    /// At its frozen footprint and one byte under, a body keeps its frozen terminal unless that terminal was too-large and the body carries string bytes.
    /// Such a body now takes its unbounded-pool terminal, and its footprint fell by exactly the removed string copies.
    /// The node floor is coefficient-independent and decides the remaining refusals.
    #[tokio::test(flavor = "current_thread")]
    async fn frozen_corpus_footprints_replay_with_only_string_charge_changes() {
        let corpus = transform_decode_corpus();
        assert_eq!(
            corpus.iter().map(|(name, _)| *name).collect::<Vec<_>>(),
            FROZEN_CORPUS_OUTCOMES
                .iter()
                .map(|frozen| frozen.name)
                .collect::<Vec<_>>(),
            "the frozen table names every corpus body in order"
        );
        let removed_copies = FROZEN_STRING_COPIES - RETAINED_STRING_COPIES;
        let too_large = comparable_outcome(request_too_large_error()).0;
        let mut admitted_by_lower_charge = Vec::new();
        let mut expected = Vec::new();
        for ((name, body), frozen) in corpus.iter().zip(FROZEN_CORPUS_OUTCOMES) {
            let has_revision = !matches!(
                *name,
                "malformed"
                    | "array body"
                    | "string body"
                    | "empty body"
                    | "raw-value token under the discriminator"
            );
            let frozen = FrozenOutcome {
                footprint: frozen.footprint
                    + if has_revision {
                        256 + 22 * FROZEN_STRING_COPIES
                    } else {
                        0
                    },
                string_bytes: frozen.string_bytes + if has_revision { 22 } else { 0 },
                ..*frozen
            };
            assert_eq!(
                footprint_of(body),
                frozen.footprint - removed_copies * frozen.string_bytes,
                "{name}: the footprint fell by exactly the removed string copies"
            );
            if !VALUE_STRING_ORACLE_EXCLUDED.contains(name)
                && let Ok(value) = serde_json::from_slice::<Value>(body)
            {
                assert_eq!(
                    frozen.string_bytes,
                    value_string_bytes(&value),
                    "{name}: the recorded string bytes are the tree's string bytes"
                );
            }

            let outcome_at = |capacity: usize| async move {
                let (handler, _store, _dir, _project) =
                    handler_with_store(Arc::new(ProducerState::default()), default_test_config());
                let pool = TestPool::with_capacity(capacity);
                let meter = ResidentMeter::new(&pool);
                let runner = transform_unit::DetachedRunner::default();
                let probe = lane_probe(body);
                let entry = PassEntry {
                    core: &handler.core,
                    route: test_route(7),
                    probe: probe.as_ref(),
                    meter: &meter,
                    runner: &runner,
                };
                let (_, outcome) = handler.dispatch_body(&entry, body).await;
                comparable_outcome(outcome)
            };
            let unbounded = outcome_at(1 << 30).await;
            assert_eq!(
                unbounded.0, frozen.unbounded,
                "{name}: the unbounded-pool terminal is unchanged"
            );
            for (capacity, recorded) in [
                (frozen.footprint, frozen.at_footprint),
                (frozen.footprint.saturating_sub(1), frozen.under_footprint),
            ] {
                let actual = outcome_at(capacity).await;
                if actual.0 == recorded {
                    if recorded == frozen.unbounded {
                        assert_eq!(
                            actual, unbounded,
                            "{name} at {capacity}: the admitted outcome is the unbounded one"
                        );
                    }
                    continue;
                }
                assert_eq!(
                    recorded, too_large,
                    "{name} at {capacity}: only a frozen too-large terminal may change"
                );
                assert!(
                    frozen.string_bytes > 0,
                    "{name} at {capacity}: only string bytes lower the charge"
                );
                assert_eq!(
                    actual, unbounded,
                    "{name} at {capacity}: the lowered charge admits the body to its unbounded-pool outcome"
                );
                admitted_by_lower_charge.push((*name, capacity));
            }
            for (capacity, recorded) in [
                (frozen.footprint, frozen.at_footprint),
                (frozen.footprint.saturating_sub(1), frozen.under_footprint),
            ] {
                let fits = frozen.footprint - removed_copies * frozen.string_bytes <= capacity;
                if recorded == too_large
                    && frozen.unbounded != too_large
                    && fits
                    && !footprint_floor_exceeds(body, capacity)
                {
                    expected.push((*name, capacity));
                }
            }
        }
        assert_eq!(
            admitted_by_lower_charge, expected,
            "every frozen too-large terminal that the lowered charge now fits becomes an admission, and nothing else changes"
        );
    }

    pub(crate) struct TestPool {
        budget: host_runtime::wire::ByteBudget,
        capacity: usize,
        reserve_calls: AtomicUsize,
    }

    impl TestPool {
        pub(crate) fn with_capacity(capacity: usize) -> Self {
            Self {
                budget: host_runtime::wire::ByteBudget::new(capacity as u64),
                capacity,
                reserve_calls: AtomicUsize::new(0),
            }
        }

        /// Reservation attempts so far, granted or not.
        fn reserve_calls(&self) -> usize {
            self.reserve_calls.load(Ordering::Relaxed)
        }

        /// Room for any body a test sends.
        pub(crate) fn unbounded() -> Self {
            Self::with_capacity(1 << 30)
        }

        /// Holds `bytes` as another request would, until the charge drops.
        fn hold(&self, bytes: usize) -> host_runtime::wire::ByteCharge {
            self.budget
                .try_charge(bytes)
                .expect("the pool has the bytes")
        }
    }

    impl ResidentReserve for TestPool {
        fn try_reserve(&self, bytes: usize) -> Option<host_runtime::wire::ByteCharge> {
            self.reserve_calls.fetch_add(1, Ordering::Relaxed);
            self.budget.try_charge(bytes)
        }

        fn capacity(&self) -> usize {
            self.capacity
        }
    }

    #[test]
    fn decode_footprint_counts_values_and_retained_string_copies() {
        // Separators inside a string are text, not values.
        let quoted = br#"{"a":"x,y,z:w,,,::"}"#;
        let bare = br#"{"a":1,"b":2,"c":3}"#;
        assert!(
            footprint_of(quoted) < footprint_of(bare),
            "commas and colons inside a string must not count as values"
        );
        // A large text block is charged once: the typed decode owns one copy of it.
        let text = "t".repeat(1 << 20);
        let body = format!(
            r#"{{"kind":"transform","messages":[{{"role":"user","content":[{{"kind":{{"type":"text","text":"{text}"}}}}]}}]}}"#
        );
        let footprint = footprint_of(body.as_bytes());
        assert!(
            footprint >= text.len() && footprint < 2 * text.len(),
            "the footprint {footprint} must cover one copy of {} string bytes and not two",
            text.len()
        );
        // Each two wire bytes can produce one value, so the footprint of a scalar-dense body
        // is far above its wire size, and string bytes are not charged as values.
        let mut dense = Vec::from(b"[1".as_slice());
        for _ in 0..10_000 {
            dense.extend_from_slice(b",1");
        }
        dense.push(b']');
        assert!(footprint_of(&dense) > dense.len() * 8);
        let mut stringy = Vec::from(b"[\"".as_slice());
        stringy.extend(std::iter::repeat_n(b'x', dense.len()));
        stringy.extend_from_slice(b"\"]");
        assert!(footprint_of(&stringy) < stringy.len() * 4);
        // A body that stops decoding partway counts the part that decoded.
        let cut = &dense[..dense.len() / 2];
        assert!(footprint_of(cut) > cut.len() * 8);
        assert!(footprint_of(cut) < footprint_of(&dense));
    }

    /// The meter charges as values are visited: a decode that fits holds at least its footprint
    /// and at most one step more; a footprint above the capacity is refused before the pool is
    /// asked, and the decode stops there.
    #[test]
    fn metered_decode_charges_incrementally_and_refuses_above_capacity() {
        let body = serde_json::to_vec(&request(vec![ck("m1", 1, "hello")])).unwrap();
        let footprint = footprint_of(&body);

        let pool = TestPool::unbounded();
        let meter = ResidentMeter::new(&pool);
        let decoded: Value = decode_metered(&body, &meter).unwrap();
        assert_eq!(decoded["kind"], "transform");
        assert_eq!(meter.needed(), footprint);
        assert!(meter.charged() >= footprint);
        assert!(meter.charged() < footprint + 2 * 1024 * 1024);
        assert_eq!(meter.refusal(), None);

        let small = TestPool::with_capacity(footprint - 1);
        let meter = ResidentMeter::new(&small);
        let failure = decode_metered::<Value>(&body, &meter).unwrap_err();
        assert!(matches!(
            failure,
            DecodeFailure::Refused(Refusal::Permanent)
        ));
        assert_eq!(meter.charged(), 0, "a refused decode releases at once");
        assert!(meter.needed() > small.capacity());
        assert!(meter.needed() <= footprint);
        assert_eq!(meter.shortfall(), None);

        // A second decode of the same body reuses the held bytes.
        let meter = ResidentMeter::new(&pool);
        assert!(decode_metered::<TransformRequest>(b"{\"kind\":\"transform\"}", &meter).is_err());
        let held = meter.charged();
        meter.restart();
        let decoded: Value = decode_metered(b"{\"kind\":\"transform\"}", &meter).unwrap();
        assert_eq!(decoded["kind"], "transform");
        assert_eq!(meter.charged(), held);
    }

    /// A small body holds at most twice its footprint, not a full batch.
    #[test]
    fn a_small_body_holds_no_more_than_twice_its_footprint() {
        for body in [
            br#"{"kind":"status","session_id":"ses"}"#.to_vec(),
            serde_json::to_vec(&request(vec![ck("m1", 1, "hello")])).unwrap(),
        ] {
            let footprint = footprint_of(&body);
            assert!(footprint < 1024 * 1024, "the body is small: {footprint}");
            let pool = TestPool::unbounded();
            let meter = ResidentMeter::new(&pool);
            let _: Value = decode_metered(&body, &meter).unwrap();
            assert!(meter.charged() >= footprint);
            assert!(
                meter.charged() <= 2 * footprint,
                "a body with footprint {footprint} holds {} bytes",
                meter.charged()
            );
        }
    }

    /// When the free pool is smaller than a full step, reservations must not scale with the
    /// parsed values.
    #[test]
    fn a_nearly_drained_pool_is_charged_in_a_bounded_number_of_acquisitions() {
        let mut body = Vec::from(b"[0".as_slice());
        for _ in 1..3_000 {
            body.extend_from_slice(b",0");
        }
        body.push(b']');
        let footprint = footprint_of(&body);
        assert!(
            footprint > 300 * 1024,
            "the body needs several batches: {footprint}"
        );

        let pool = TestPool::with_capacity(10 * 1024 * 1024);
        // Leave less than a full step free, and less than the body needs.
        let holder = pool.hold(pool.capacity() - footprint * 3 / 4);
        let meter = ResidentMeter::new(&pool);
        let failure = decode_metered::<Value>(&body, &meter).unwrap_err();
        assert!(matches!(
            failure,
            DecodeFailure::Refused(Refusal::Transient)
        ));
        let calls = pool.reserve_calls();
        assert!(
            calls < 100,
            "{calls} reservation attempts to take {} bytes; one per value is a cliff",
            footprint * 3 / 4
        );
        drop(holder);
    }

    /// The pool-drain witness for the shortfall path: a body that fits the capacity finds the
    /// pool held by another request, is refused as transient, and is served once the holder
    /// releases.
    #[test]
    fn a_drained_pool_refuses_a_fitting_body_as_transient_and_records_the_shortfall() {
        let body = serde_json::to_vec(&request(vec![ck("m1", 1, "hello")])).unwrap();
        let footprint = footprint_of(&body);
        let pool = TestPool::with_capacity(footprint + 4096);
        let before = shortfall_count();

        let holder = pool.hold(footprint / 2);
        let meter = ResidentMeter::new(&pool);
        let failure = decode_metered::<Value>(&body, &meter).unwrap_err();
        assert!(matches!(
            failure,
            DecodeFailure::Refused(Refusal::Transient)
        ));
        assert!(meter.needed() <= pool.capacity());
        assert_eq!(meter.charged(), 0, "a refused decode releases at once");
        assert!(shortfall_count() > before);
        let marker = meter.shortfall().unwrap();
        assert!(marker.needed <= marker.capacity);
        assert!(marker.charged < marker.needed);
        assert_eq!(marker.capacity, pool.capacity());
        assert_eq!(
            comparable_outcome(resident_refusal(Refusal::Transient)),
            comparable_outcome(resident_capacity_error())
        );
        drop(meter);

        drop(holder);
        let meter = ResidentMeter::new(&pool);
        let decoded: Value = decode_metered(&body, &meter).unwrap();
        assert_eq!(decoded["kind"], "transform");

        // A body the pool could never hold is `queue_full` while another request holds the
        // pool, since classifying it would mean a second parse outside the pool, and too
        // large once the pool has room to count it.
        let oversized = format!(
            r#"{{"kind":"transform","x":[{}]}}"#,
            "1,".repeat(200_000) + "1"
        );
        let pool = TestPool::with_capacity(footprint_of(oversized.as_bytes()) - 1);
        let holder = pool.hold(pool.capacity() / 2);
        let meter = ResidentMeter::new(&pool);
        let failure = decode_metered::<Value>(oversized.as_bytes(), &meter).unwrap_err();
        assert!(matches!(
            failure,
            DecodeFailure::Refused(Refusal::Transient)
        ));
        assert_eq!(
            comparable_outcome(resident_refusal(Refusal::Transient)),
            comparable_outcome(resident_capacity_error())
        );
        drop(holder);
        let meter = ResidentMeter::new(&pool);
        let failure = decode_metered::<Value>(oversized.as_bytes(), &meter).unwrap_err();
        assert!(matches!(
            failure,
            DecodeFailure::Refused(Refusal::Permanent)
        ));
    }

    /// Bodies whose byte-derived footprint exceeds pool capacity are rejected before decoding
    /// without reserving pool bytes.
    #[tokio::test(flavor = "current_thread")]
    async fn a_doomed_body_is_refused_without_touching_the_pool() {
        let (handler, _store, _dir, _project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let dense_values = || "0,".repeat(200_000) + "0";
        // One body takes the tree lane, one is a complete unpaged transform request whose
        // values sit under an ignored field, so the direct decode would refuse it.
        let bodies = [
            format!(
                r#"{{"kind":"transform","transform_page_id":"p","x":[{}]}}"#,
                dense_values()
            ),
            format!(
                r#"{{"kind":"transform","v":2,"session_id":"ses","serializer_profile":"owned-llmrunner","render_config":"cfg","messages":[],"junk":[{}]}}"#,
                dense_values()
            ),
        ];
        for body in bodies {
            let body = body.into_bytes();
            let pool = TestPool::with_capacity(footprint_of(&body) / 2);
            let meter = ResidentMeter::new(&pool);
            let runner = transform_unit::DetachedRunner::default();
            let probe = probe_request(&body);
            let entry = PassEntry {
                core: &handler.core,
                route: test_route(7),
                probe: probe.as_ref(),
                meter: &meter,
                runner: &runner,
            };
            let (lane, outcome) = handler.dispatch_body(&entry, &body).await;
            assert_eq!(
                pool.reserve_calls(),
                0,
                "a doomed body must not hold the pool while it is parsed"
            );
            assert_eq!(
                comparable_outcome(outcome),
                comparable_outcome(request_too_large_error())
            );
            assert_eq!(lane, BodyLane::Unread);
            assert_eq!(meter.needed(), 0, "no value was built");
        }
    }

    /// The byte-derived floor never exceeds the footprint the decode counts, so it refuses no
    /// body the meter would admit.
    #[test]
    fn footprint_floor_never_exceeds_the_decoded_footprint() {
        for (name, body) in transform_decode_corpus() {
            if serde_json::from_slice::<Value>(&body).is_err() {
                continue;
            }
            assert!(
                footprint_floor(&body) <= footprint_of(&body),
                "{name}: floor {} above footprint {}",
                footprint_floor(&body),
                footprint_of(&body)
            );
        }
    }

    /// A refused decode ends the request with the prior code and touches nothing the dispatch
    /// would: no ticket, no route channel, no store row.
    #[tokio::test(flavor = "current_thread")]
    async fn a_refused_decode_has_no_dispatch_side_effect() {
        let (handler, store, _dir, project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let body = serde_json::to_vec(&request(vec![ck("m1", 1, "hello")])).unwrap();
        let footprint = footprint_of(&body);
        let route = test_route(7);
        // `DISPATCH_HEALTH` is process-wide and moves under other tests, so the witnesses are
        // the handler's own route table and the store, which a ticket's accept would touch.
        let route_channel_bound = |handler: &Handler| {
            handler
                .transform_route_channels
                .lock()
                .expect("route channels mutex")
                .contains_key(&route)
        };
        let runner = transform_unit::DetachedRunner::default();
        let probe = probe_request(&body);

        for (pool, expected) in [
            (
                TestPool::with_capacity(footprint / 2),
                request_too_large_error(),
            ),
            (
                TestPool::with_capacity(footprint + 4096),
                resident_capacity_error(),
            ),
        ] {
            let holder = pool.hold(pool.capacity() / 2);
            let meter = ResidentMeter::new(&pool);
            let entry = PassEntry {
                core: &handler.core,
                route: test_route(7),
                probe: probe.as_ref(),
                meter: &meter,
                runner: &runner,
            };
            let (_, outcome) = handler.dispatch_body(&entry, &body).await;
            assert_eq!(comparable_outcome(outcome), comparable_outcome(expected));
            drop(meter);
            drop(holder);
            assert!(!route_channel_bound(&handler), "a refusal bound the route");
        }
        assert!(!handler.module_knows_transform_session("ses", &project));
        assert!(store.load("ses").unwrap().row_version.is_none());

        // The same body with room is served, and only then is the route bound.
        let pool = TestPool::unbounded();
        let meter = ResidentMeter::new(&pool);
        let entry = PassEntry {
            core: &handler.core,
            route: test_route(7),
            probe: probe.as_ref(),
            meter: &meter,
            runner: &runner,
        };
        let (lane, outcome) = handler.dispatch_body(&entry, &body).await;
        assert_eq!(lane, BodyLane::Direct);
        assert_eq!(comparable_outcome(outcome).0, "response");
        assert!(route_channel_bound(&handler));
    }

    #[test]
    fn transform_snapshot_cache_is_generation_safe_and_lru_bounded() {
        let request = |session_id: &str| {
            let mut request = transform_request(vec![ck("m1", 1, "text")], 1, 200_000);
            request.session_id = session_id.to_string();
            Arc::new(request)
        };
        let mut cache = TransformSnapshotCache::new(10);
        assert!(!cache.generation_present_in_flight_or_ready("a", 1));
        let a = cache.begin("a");
        assert!(cache.generation_present_in_flight_or_ready("a", a));
        cache.finish_ready("a", a, request("a"), 1, 5);
        assert!(cache.generation_present_in_flight_or_ready("a", a));
        let b = cache.begin("b");
        cache.finish_ready("b", b, request("b"), 2, 5);
        assert!(matches!(cache.get("a"), TransformSnapshotLookup::Ready(_)));

        let c = cache.begin("c");
        cache.finish_ready("c", c, request("c"), 3, 5);
        assert!(matches!(cache.get("b"), TransformSnapshotLookup::Missing));
        assert!(matches!(cache.get("a"), TransformSnapshotLookup::Ready(_)));
        assert!(matches!(cache.get("c"), TransformSnapshotLookup::Ready(_)));
        assert_eq!(cache.ready_bytes, 10);

        let stale = cache.begin("a");
        let current = cache.begin("a");
        cache.finish_ready("a", stale, request("stale"), 4, 1);
        assert!(matches!(cache.get("a"), TransformSnapshotLookup::InFlight));
        cache.finish_ready("a", current, request("a"), 5, 4);
        assert!(cache.ready_generation_matches("a", current));
        assert!(cache.ready_bytes <= cache.max_ready_bytes);

        let oversized = cache.begin("oversized");
        cache.finish_ready("oversized", oversized, request("oversized"), 0, 11);
        assert!(matches!(
            cache.get("oversized"),
            TransformSnapshotLookup::Missing
        ));
    }

    #[test]
    fn snapshot_lease_budget_survives_cache_churn_and_releases_exact_charge() {
        let request = |session_id: &str| {
            let mut request = transform_request(vec![ck("m1", 1, "text")], 1, 200_000);
            request.session_id = session_id.to_string();
            Arc::new(request)
        };
        let mut cache = TransformSnapshotCache::new(10);
        {
            let mut budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            budget.max_bytes = 10;
            budget.max_count = 1;
        }
        let a = cache.begin("a");
        cache.finish_ready("a", a, request("a"), 0, 5);
        let b = cache.begin("b");
        cache.finish_ready("b", b, request("b"), 0, 5);
        let lease = match cache.get("a") {
            TransformSnapshotLookup::Ready(lease) => lease,
            _ => panic!("first lease must fit"),
        };

        // A leased Arc remains charged after its map entry is evicted, until its guard drops.
        // Map and lease accounting remain independently bounded until the leased Arc's guard drops.
        let c = cache.begin("c");
        cache.finish_ready("c", c, request("c"), 0, 6);
        assert!(cache.ready_bytes <= cache.max_ready_bytes);
        assert!(matches!(
            cache.get("c"),
            TransformSnapshotLookup::LeaseBudgetExceeded
        ));
        {
            let budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            assert_eq!((budget.count, budget.bytes), (1, 5));
            assert!(budget.count <= budget.max_count);
            assert!(budget.bytes <= budget.max_bytes);
        }
        assert_eq!(lease.request.session_id, "a");
        drop(lease);
        {
            let budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            assert_eq!((budget.count, budget.bytes), (0, 0));
        }
        assert!(matches!(cache.get("c"), TransformSnapshotLookup::Ready(_)));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn ready_snapshot_holds_no_native_payload_and_a_lease_pins_its_generation() {
        assert_eq!(TRANSFORM_SNAPSHOT_BUDGET_BYTES, 64 * 1024 * 1024);
        assert_eq!(ACTIVE_SNAPSHOT_LEASE_BUDGET_BYTES, 64 * 1024 * 1024);
        assert_eq!(MAX_ACTIVE_SNAPSHOT_LEASES, 8);
        let (handler, _store, _dir, _project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let session = "ses";
        let request = |text: &str| {
            native_cache_request(
                session,
                vec![ck("snapshot-1", 1, text)],
                vec![json!({
                    "info": { "id": "snapshot-1", "role": "user" },
                    "parts": [{ "type": "text", "text": text }],
                    "provider_data": "p".repeat(64 * 1024),
                })],
            )
        };
        let first =
            call_transform_request(&handler, serde_json::to_value(request("one")).unwrap()).await;
        assert_eq!(first["status"], "ok", "{first}");
        let lease = match handler.transform_snapshots.lock().unwrap().get(session) {
            TransformSnapshotLookup::Ready(lease) => lease,
            _ => panic!("the accepted pass must publish a ready snapshot"),
        };
        // The snapshot keeps the CK input and is charged for it alone, not the 64 KiB native payload.
        assert!(lease.request.native_messages.is_none());
        assert!(!lease.request.serve_native);
        assert_eq!(lease.request.messages.len(), 1);
        assert_eq!(
            lease.retained_bytes,
            lease.request.snapshot_retained_bytes()
        );
        assert!(lease.retained_bytes < 64 * 1024, "{}", lease.retained_bytes);
        let pinned = lease.generation;

        let second =
            call_transform_request(&handler, serde_json::to_value(request("two")).unwrap()).await;
        assert_eq!(second["status"], "ok", "{second}");
        {
            let snapshots = handler.transform_snapshots.lock().unwrap();
            assert!(!snapshots.ready_generation_matches(session, pinned));
            let budget = snapshots.active_leases.lock().unwrap();
            assert_eq!((budget.count, budget.bytes), (1, lease.retained_bytes));
        }
        // Replacement never frees or changes a held snapshot.
        assert_eq!(lease.generation, pinned);
        assert_eq!(lease.request.messages[0].ck, ck("snapshot-1", 1, "one").ck);
        let snapshots = Arc::clone(&handler.transform_snapshots.lock().unwrap().active_leases);
        drop(lease);
        assert_eq!(
            {
                let budget = snapshots.lock().unwrap();
                (budget.count, budget.bytes)
            },
            (0, 0)
        );
    }

    #[test]
    fn ready_snapshot_shares_messages_and_charges_at_least_their_bytes() {
        let charge = |text: &str| {
            let mut request = transform_request(vec![ck("m1", 1, text)], 1, 200_000);
            request.serve_native = true;
            request.native_messages = Some(vec![Arc::new(json!({ "info": { "id": "m1" } }))]);
            let snapshot = request.ready_snapshot();
            assert!(snapshot.native_messages.is_none());
            assert!(!snapshot.serve_native);
            assert!(Arc::ptr_eq(&snapshot.messages[0], &request.messages[0]));
            let bytes = snapshot.snapshot_retained_bytes();
            let ingress = snapshot
                .messages
                .iter()
                .map(|message| retained_size::ingress_message_retained_bytes(message))
                .sum::<usize>();
            assert!(bytes >= ingress, "{bytes} < {ingress}");
            bytes
        };
        let grown = 4096;
        assert!(charge(&"x".repeat(grown + 1)) >= charge("x") + grown);
    }

    #[test]
    fn snapshot_lease_budget_rejects_second_lease_on_bytes_alone() {
        let request = |session_id: &str| {
            let mut request = transform_request(vec![ck("m1", 1, "text")], 1, 200_000);
            request.session_id = session_id.to_string();
            Arc::new(request)
        };
        let mut cache = TransformSnapshotCache::new(16);
        {
            let mut budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            budget.max_bytes = 9;
            budget.max_count = 8;
        }
        let first_generation = cache.begin("first");
        cache.finish_ready("first", first_generation, request("first"), 0, 5);
        let second_generation = cache.begin("second");
        cache.finish_ready("second", second_generation, request("second"), 0, 5);

        let first = match cache.get("first") {
            TransformSnapshotLookup::Ready(lease) => lease,
            _ => panic!("first lease must fit within both budgets"),
        };
        assert!(matches!(
            cache.get("second"),
            TransformSnapshotLookup::LeaseBudgetExceeded
        ));
        {
            let budget = cache
                .active_leases
                .lock()
                .expect("snapshot lease budget mutex");
            assert_eq!(budget.count, 1);
            assert!(
                budget.count < budget.max_count,
                "the count cap must not decide this case"
            );
            assert_eq!(budget.bytes, 5);
        }

        drop(first);
        assert!(matches!(
            cache.get("second"),
            TransformSnapshotLookup::Ready(_)
        ));
    }

    #[derive(Clone, Copy, PartialEq, Eq)]
    enum BlockingLifecycleCall {
        Start,
        Reattach,
    }

    struct BlockingLifecycleState {
        call: BlockingLifecycleCall,
        cancel: Mutex<Option<CancellationToken>>,
        entered: AtomicBool,
        exited: AtomicBool,
    }

    impl BlockingLifecycleState {
        fn new(call: BlockingLifecycleCall) -> Arc<Self> {
            Arc::new(Self {
                call,
                cancel: Mutex::new(None),
                entered: AtomicBool::new(false),
                exited: AtomicBool::new(false),
            })
        }

        async fn block(&self) -> HistorySummarizerProducerError {
            self.entered.store(true, Ordering::SeqCst);
            let cancel = self
                .cancel
                .lock()
                .unwrap()
                .clone()
                .expect("test cancellation installed");
            cancel.cancelled().await;
            self.exited.store(true, Ordering::SeqCst);
            HistorySummarizerProducerError::TimedOut
        }
    }

    struct BlockingLifecycleFactory {
        state: Arc<BlockingLifecycleState>,
    }

    #[async_trait]
    impl HistorySummarizerProducerFactory for BlockingLifecycleFactory {
        async fn connect(
            &self,
            _project_root: &Path,
            _harness: &str,
            _credential_fingerprints: &std::collections::BTreeMap<String, String>,
        ) -> Result<Box<dyn HistorySummarizerProducerDriver + Send>, HistorySummarizerProducerError>
        {
            Ok(Box::new(BlockingLifecycleProducer {
                state: Arc::clone(&self.state),
            }))
        }
    }

    struct BlockingLifecycleProducer {
        state: Arc<BlockingLifecycleState>,
    }

    #[async_trait]
    impl HistorySummarizerProducerDriver for BlockingLifecycleProducer {
        async fn bind_session(
            &mut self,
            _session_id: &str,
        ) -> Result<(), HistorySummarizerProducerError> {
            Ok(())
        }

        async fn start(
            &mut self,
            _session_id: &str,
            _system: &str,
            _prompt: &str,
            _model: &str,
        ) -> Result<RunHandle, HistorySummarizerProducerError> {
            if self.state.call == BlockingLifecycleCall::Start {
                return Err(self.state.block().await);
            }
            Ok(RunHandle {
                run_id: "unused".to_owned(),
            })
        }

        async fn await_output(
            &mut self,
            _run_id: &str,
        ) -> Result<ProducerOutput, HistorySummarizerProducerError> {
            Err(HistorySummarizerProducerError::TimedOut)
        }

        async fn status(
            &mut self,
            _run_id: &str,
        ) -> Result<RunState, HistorySummarizerProducerError> {
            if self.state.call == BlockingLifecycleCall::Reattach {
                return Err(self.state.block().await);
            }
            Ok(RunState::Active)
        }

        async fn cancel(&mut self, _run_id: &str) -> Result<(), HistorySummarizerProducerError> {
            Ok(())
        }

        async fn close(&mut self) -> Result<(), HistorySummarizerProducerError> {
            Ok(())
        }
    }

    #[derive(Default)]
    struct ProducerState {
        connects: AtomicUsize,
        starts: AtomicUsize,
        start_errors: Mutex<VecDeque<Result<RunHandle, HistorySummarizerProducerError>>>,
        binds: AtomicUsize,
        statuses: AtomicUsize,
        await_outputs: AtomicUsize,
        redrains: AtomicUsize,
        block_output: std::sync::atomic::AtomicBool,
        notify: Notify,
        connect_errors: Mutex<VecDeque<HistorySummarizerProducerError>>,
        await_results: Mutex<VecDeque<Result<ProducerOutput, HistorySummarizerProducerError>>>,
        outputs: Mutex<VecDeque<String>>,
        next_fact: Mutex<Option<String>>,
        prompts: Mutex<Vec<String>>,
        harnesses: Mutex<Vec<String>>,
        sessions: Mutex<Vec<String>>,
        purges: Mutex<Vec<String>>,
        /// `session_events` preserves start/purge order that separate logs lose.
        session_events: Mutex<Vec<String>>,
        purge_errors: Mutex<VecDeque<HistorySummarizerProducerError>>,
        await_timeouts: Mutex<Vec<Duration>>,
        on_await_output: Mutex<Option<Box<dyn FnOnce() + Send>>>,
        /// Runs once, on entry to the next `start`, before it is counted.
        on_start: Mutex<Option<Box<dyn FnOnce() + Send>>>,
        /// Scripted `status` answers; `Active` once the queue is drained.
        status_results: Mutex<VecDeque<RunState>>,
        /// Every run id `status` was asked about, in order.
        status_runs: Mutex<Vec<String>>,
        /// `status` waits on `notify` while `block_status` is set, simulating a
        /// runtime that accepts the probe but never replies.
        block_status: std::sync::atomic::AtomicBool,
        /// `connect` waits on `notify` while `block_connect` is set.
        block_connect: std::sync::atomic::AtomicBool,
        /// `start` fails permanently with this host message for prompts whose chunk starts at this ordinal.
        refused_chunk: Mutex<Option<(u64, &'static str)>>,
    }

    struct TestProducerFactory {
        state: Arc<ProducerState>,
    }

    #[async_trait]
    impl HistorySummarizerProducerFactory for TestProducerFactory {
        async fn connect(
            &self,
            _project_root: &Path,
            harness: &str,
            _credential_fingerprints: &std::collections::BTreeMap<String, String>,
        ) -> Result<Box<dyn HistorySummarizerProducerDriver + Send>, HistorySummarizerProducerError>
        {
            self.state.connects.fetch_add(1, Ordering::SeqCst);
            self.state
                .harnesses
                .lock()
                .expect("harnesses mutex")
                .push(harness.to_string());
            while self.state.block_connect.load(Ordering::SeqCst) {
                self.state.notify.notified().await;
            }
            if let Some(err) = self
                .state
                .connect_errors
                .lock()
                .expect("connect errors mutex")
                .pop_front()
            {
                return Err(err);
            }
            Ok(Box::new(TestProducer {
                state: Arc::clone(&self.state),
                bound_session: None,
            }))
        }
    }

    struct TestProducer {
        state: Arc<ProducerState>,
        bound_session: Option<String>,
    }

    #[async_trait]
    impl HistorySummarizerProducerDriver for TestProducer {
        async fn bind_session(
            &mut self,
            session_id: &str,
        ) -> Result<(), HistorySummarizerProducerError> {
            self.state.binds.fetch_add(1, Ordering::SeqCst);
            self.bound_session = Some(session_id.to_string());
            Ok(())
        }

        async fn start(
            &mut self,
            session_id: &str,
            _system: &str,
            prompt: &str,
            _model: &str,
        ) -> Result<RunHandle, HistorySummarizerProducerError> {
            if let Some(hook) = self.state.on_start.lock().expect("start hook mutex").take() {
                hook();
            }
            let n = self.state.starts.fetch_add(1, Ordering::SeqCst) + 1;
            self.state
                .sessions
                .lock()
                .expect("sessions mutex")
                .push(session_id.to_string());
            self.state
                .session_events
                .lock()
                .expect("session events mutex")
                .push(format!("start:{session_id}"));
            self.state
                .prompts
                .lock()
                .expect("prompts mutex")
                .push(prompt.to_string());
            let refused = *self
                .state
                .refused_chunk
                .lock()
                .expect("refused chunk mutex");
            if let Some((refused_start, detail)) = refused
                && prompt_ordinal_range(prompt).map(|(start, _)| start) == Some(refused_start)
            {
                return Err(HistorySummarizerProducerError::RunFailed {
                    run_id: format!("run-{n}"),
                    detail: detail.to_string(),
                    classification: Some(history_summarizer_producer::ErrorClassification {
                        class: history_summarizer_producer::ErrorClass::Permanent,
                        retry_after_secs: None,
                    }),
                    class_field_present: true,
                });
            }
            if let Some(result) = self
                .state
                .start_errors
                .lock()
                .expect("start errors mutex")
                .pop_front()
            {
                return result;
            }
            let output = match self.state.next_fact.lock().expect("next fact mutex").take() {
                Some(fact) => {
                    let (start, end) = prompt_ordinal_range(prompt).unwrap_or((1, 3));
                    history_summarizer_output_with_fact(start, end, &fact)
                }
                None => history_summarizer_output_for_prompt(prompt),
            };
            self.state
                .outputs
                .lock()
                .expect("outputs mutex")
                .push_back(output);
            Ok(RunHandle {
                run_id: format!("run-{n}"),
            })
        }

        async fn await_output(
            &mut self,
            _run_id: &str,
        ) -> Result<ProducerOutput, HistorySummarizerProducerError> {
            self.state.await_outputs.fetch_add(1, Ordering::SeqCst);
            if let Some(hook) = self
                .state
                .on_await_output
                .lock()
                .expect("await-output hook mutex")
                .take()
            {
                hook();
            }
            while self.state.block_output.load(Ordering::SeqCst) {
                self.state.notify.notified().await;
            }
            if let Some(result) = self
                .state
                .await_results
                .lock()
                .expect("await results mutex")
                .pop_front()
            {
                return result;
            }
            let text = self
                .state
                .outputs
                .lock()
                .expect("outputs mutex")
                .pop_front()
                .unwrap_or_else(|| history_summarizer_output(1, 3, "reattached summary"));
            Ok(ProducerOutput {
                text,
                length_capped: false,
            })
        }

        async fn await_output_with_timeout(
            &mut self,
            run_id: &str,
            timeout: Duration,
        ) -> Result<ProducerOutput, HistorySummarizerProducerError> {
            self.state
                .await_timeouts
                .lock()
                .expect("await timeouts mutex")
                .push(timeout);
            // The real producer gives up at `timeout`; a blocked output that outlives it is the timed-out attempt the caller then records.
            match tokio::time::timeout(timeout, self.await_output(run_id)).await {
                Ok(result) => result,
                Err(_) => Err(HistorySummarizerProducerError::TimedOut),
            }
        }

        async fn redrain_output_with_timeout(
            &mut self,
            run_id: &str,
            timeout: Duration,
        ) -> Result<ProducerOutput, HistorySummarizerProducerError> {
            self.state.redrains.fetch_add(1, Ordering::SeqCst);
            match tokio::time::timeout(timeout, self.await_output(run_id)).await {
                Ok(result) => result,
                Err(_) => Err(HistorySummarizerProducerError::TimedOut),
            }
        }

        async fn status(
            &mut self,
            run_id: &str,
        ) -> Result<RunState, HistorySummarizerProducerError> {
            self.state.statuses.fetch_add(1, Ordering::SeqCst);
            // The real producer routes `status` through the bound session and answers `MissingSession` otherwise.
            let Some(session) = self.bound_session.clone() else {
                return Err(HistorySummarizerProducerError::Protocol(
                    "status before bind_session".to_string(),
                ));
            };
            self.state
                .status_runs
                .lock()
                .expect("status runs mutex")
                .push(format!("{session}:{run_id}"));
            while self.state.block_status.load(Ordering::SeqCst) {
                self.state.notify.notified().await;
            }
            Ok(self
                .state
                .status_results
                .lock()
                .expect("status results mutex")
                .pop_front()
                .unwrap_or(RunState::Active))
        }

        async fn cancel(&mut self, _run_id: &str) -> Result<(), HistorySummarizerProducerError> {
            Ok(())
        }

        async fn close(&mut self) -> Result<(), HistorySummarizerProducerError> {
            Ok(())
        }

        async fn purge_session(
            &mut self,
            session_id: &str,
        ) -> Result<(), HistorySummarizerProducerError> {
            self.state
                .purges
                .lock()
                .expect("purges mutex")
                .push(session_id.to_string());
            self.state
                .session_events
                .lock()
                .expect("session events mutex")
                .push(format!("purge:{session_id}"));
            match self
                .state
                .purge_errors
                .lock()
                .expect("purge errors mutex")
                .pop_front()
            {
                Some(err) => Err(err),
                None => Ok(()),
            }
        }
    }

    fn handler_with_store(
        state: Arc<ProducerState>,
        config: DaemonConfig,
    ) -> (Handler, Arc<MemoryStore>, tempfile::TempDir, PathBuf) {
        handler_with_store_and_resolver(state, config, Arc::new(MissingSessionResolver))
    }

    fn handler_with_store_and_resolver(
        state: Arc<ProducerState>,
        config: DaemonConfig,
        resolver: Arc<dyn SessionResolver>,
    ) -> (Handler, Arc<MemoryStore>, tempfile::TempDir, PathBuf) {
        let dir = tempfile::tempdir().unwrap();
        let data_home = dir.path().join("data");
        std::fs::create_dir_all(&data_home).unwrap();
        let store =
            Arc::new(MemoryStore::open(&dev_descriptor_at(data_home.to_str().unwrap())).unwrap());
        let handler = Handler::with_producer_factory_config_resolver(
            Arc::new(TestProducerFactory { state }),
            config,
            resolver,
        );
        handler.install_store_for_test(Arc::clone(&store));
        let project = dir.path().join("project");
        std::fs::create_dir_all(&project).unwrap();
        handler.bind_route(test_route(7), binding(project.to_str().unwrap(), "ses"));
        (handler, store, dir, project)
    }

    async fn handler_with_store_and_kernel(
        state: Arc<ProducerState>,
        config: DaemonConfig,
    ) -> (Handler, Arc<MemoryStore>, tempfile::TempDir, PathBuf) {
        let (handler, store, dir, project) = handler_with_store(state, config);
        let root = dir.path().join("kernel");
        handler
            .kernel
            .open(root, StoreOpenPolicy::default(), handler.cancel.clone())
            .await;
        assert_eq!(handler.kernel.state(), kernel_routes::KernelState::Ready);
        (handler, store, dir, project)
    }

    #[tokio::test]
    async fn automatic_capture_routes_reject_foreign_or_malformed_scope_before_work() {
        let state = Arc::new(ProducerState::default());
        let (handler, store, _dir, project) =
            handler_with_store(Arc::clone(&state), default_test_config());
        for method in [
            "memory.capture",
            "memory.capture.next",
            "memory.capture.submit",
            "memory.capture.status",
        ] {
            for (field, value) in [
                ("project_root", json!("/another-project")),
                ("project_root", Value::Null),
                ("project_root", json!(17)),
                ("project_root", json!(".")),
                ("unexpected", json!(true)),
            ] {
                let mut request = json!({"method":method,"v":2,"session_id":"ses"});
                request[field] = value;
                let outcome = match method {
                    "memory.capture" => {
                        handler.handle_memory_capture(test_route(7), &request).await
                    }
                    "memory.capture.next" => {
                        handler
                            .handle_native_capture_next(test_route(7), &request)
                            .await
                    }
                    "memory.capture.submit" => {
                        handler
                            .handle_native_capture_submit(test_route(7), &request)
                            .await
                    }
                    _ => handler.handle_memory_capture_status(test_route(7), &request),
                };
                assert!(
                    matches!(outcome, PreparedOutcome::Error { ref code, .. } if code == "invalid_params"),
                    "{method}: {outcome:?}"
                );
            }
        }
        assert_eq!(state.starts.load(Ordering::SeqCst), 0);
        assert_eq!(
            store
                .memory_capture_status(&capture_key(&project))
                .unwrap()
                .pending,
            0
        );
        let status = handler.handle_memory_capture_status(
            test_route(7),
            &json!({
                "method":"memory.capture.status","v":2,"session_id":"ses","project_root":project,
            }),
        );
        assert_eq!(tool_body(status)["state"], "available");
    }

    #[tokio::test]
    async fn automatic_capture_commits_once_and_is_explicitly_retrievable() {
        let state = Arc::new(ProducerState::default());
        let (handler, store, _dir, project) =
            handler_with_store_and_kernel(Arc::clone(&state), default_test_config()).await;
        handler.bind_route(
            test_route(7),
            SessionBinding {
                config: DaemonConfig {
                    memory_auto_capture: true,
                    ..default_test_config()
                },
                ..binding_with_harness(project.to_str().unwrap(), "pi", "ses")
            },
        );

        let request = json!({"method":"memory.capture","v":2,"session_id":"ses","model":"test/model","messages":[{"id":"native-user-1","role":"user","text":"Use port 4321 for staging. Now fix the test."}]});
        assert_eq!(
            tool_body(handler.handle_memory_capture(test_route(7), &request).await)["state"],
            "accepted"
        );
        assert_eq!(
            state.starts.load(Ordering::SeqCst),
            0,
            "checkpoint must not run a daemon model"
        );
        let next = json!({"method":"memory.capture.next","v":2,"session_id":"ses","model":"custom-native/model"});
        let work = tool_body(
            handler
                .handle_native_capture_next(test_route(7), &next)
                .await,
        );
        assert_eq!(work["state"], "work");
        let prompt: Value = serde_json::from_str(work["prompt"].as_str().unwrap()).unwrap();
        let output = json!({"version":1,"decisions":prompt["messages"].as_array().unwrap().iter().map(|message| json!({
            "message_id":message["id"],"memories":[{"category":"CONFIG_VALUES","content":"Production uses port 4321.","quote":"Use port 4321 for staging."}]
        })).collect::<Vec<_>>()});
        let submission = json!({"method":"memory.capture.submit","v":2,"session_id":"ses","lease":work["lease"],"model":work["model"],"output":output.to_string()});
        assert_eq!(
            tool_body(
                handler
                    .handle_native_capture_submit(test_route(7), &submission)
                    .await
            )["state"],
            "processed"
        );
        assert_eq!(
            tool_body(
                handler
                    .handle_native_capture_submit(test_route(7), &submission)
                    .await
            )["state"],
            "stale"
        );
        assert_eq!(
            tool_body(
                handler
                    .handle_native_capture_next(test_route(7), &next)
                    .await
            )["state"],
            "ready"
        );
        let status = store.memory_capture_status(&capture_key(&project)).unwrap();
        assert_eq!(status.completed, 1);
        assert_eq!(status.pending, 0);
        let memories = kernel_routes::read::read_visible(
            &handler.kernel.kernel_store().unwrap(),
            &kernel_routes::ProjectBinding::new(&project),
            kernel::Surface::ExplicitSearch,
            None,
            kernel_routes::read::RowSelection::DomainDecisions("memory"),
        )
        .unwrap();
        assert_eq!(
            memories.rows.len(),
            1,
            "captured facts must be retrievable, not merely stored"
        );
        assert_eq!(
            memories.rows[0].visibility,
            kernel::SurfaceVisibility::Labeled
        );
        assert_eq!(
            memories.decisions.values().next().unwrap().payload.summary,
            "User stated: Use port 4321 for staging.",
            "store the attributed source quotation, not the extractor's broadened environment"
        );
        let injected = canonical_memory::read_project_memory(
            &handler.kernel,
            &kernel_routes::ProjectBinding::new(&project),
            now_ms(),
            4000.0,
        );
        assert!(
            injected.rows().is_empty(),
            "extraction must not promote model inference into trusted automatic context"
        );
        assert_eq!(
            tool_body(handler.handle_memory_capture(test_route(7), &request).await)["state"],
            "accepted"
        );
        assert_eq!(state.starts.load(Ordering::SeqCst), 0);
        assert_eq!(
            store
                .memory_capture_status(&capture_key(&project))
                .unwrap()
                .completed,
            1
        );
    }

    #[tokio::test]
    async fn native_capture_leases_expire_and_never_publish_stale_or_deleted_sources() {
        let state = Arc::new(ProducerState::default());
        let (handler, store, _dir, project) =
            handler_with_store_and_kernel(Arc::clone(&state), default_test_config()).await;
        handler.bind_route(
            test_route(7),
            SessionBinding {
                config: DaemonConfig {
                    memory_auto_capture: true,
                    ..default_test_config()
                },
                ..binding_with_harness(project.to_str().unwrap(), "pi", "ses")
            },
        );
        let source = json!({"method":"memory.capture","v":2,"session_id":"ses","messages":[{"id":"u1","role":"user","text":"Use port 4321 for staging."}]});
        assert_eq!(
            tool_body(handler.handle_memory_capture(test_route(7), &source).await)["state"],
            "accepted"
        );
        let next = json!({"method":"memory.capture.next","v":2,"session_id":"ses","model":"custom-native/model"});
        let first = tool_body(
            handler
                .handle_native_capture_next(test_route(7), &next)
                .await,
        );
        assert_eq!(first["state"], "work");
        assert_eq!(
            tool_body(
                handler
                    .handle_native_capture_next(test_route(7), &next)
                    .await
            )["state"],
            "pending"
        );
        handler
            .native_capture
            .lock()
            .unwrap()
            .expire_ready_for_test();
        // By the time a 180 s lease has lapsed, the issued dispatch's retry
        // deadline (at most 128 s) has passed too; the clock does not run here.
        store
            .execute_tag_sql_for_test("UPDATE memory_capture_jobs SET retry_at_ms=0")
            .unwrap();
        let second = tool_body(
            handler
                .handle_native_capture_next(test_route(7), &next)
                .await,
        );
        assert_eq!(second["state"], "work");
        assert_ne!(first["lease"], second["lease"]);
        let text = json!({"version":1,"decisions":[{"message_id":"source_1","memories":[{"category":"CONFIG_VALUES","content":"Port 4321.","quote":"Use port 4321 for staging."}]}]}).to_string();
        let mut submit = json!({"method":"memory.capture.submit","v":2,"session_id":"ses","lease":first["lease"],"model":first["model"],"output":text});
        assert_eq!(
            tool_body(
                handler
                    .handle_native_capture_submit(test_route(7), &submit)
                    .await
            )["state"],
            "stale"
        );
        submit["lease"] = second["lease"].clone();
        submit["model"] = json!("different/model");
        assert!(
            matches!(handler.handle_native_capture_submit(test_route(7), &submit).await, PreparedOutcome::Error { ref code, .. } if code == "invalid_params")
        );
        submit["model"] = second["model"].clone();
        let deleted = handler
            .core
            .handle_session_delete_value(
                test_route(7),
                &json!({"method":"session.delete","v":1,"session_id":"ses"}),
            )
            .await;
        assert!(!matches!(deleted, PreparedOutcome::Error { .. }));
        assert_eq!(
            tool_body(
                handler
                    .handle_native_capture_submit(test_route(7), &submit)
                    .await
            )["state"],
            "processed"
        );
        assert_eq!(
            store
                .memory_capture_status(&capture_key(&project))
                .unwrap()
                .completed,
            0
        );
        let memories = kernel_routes::read::read_visible(
            &handler.kernel.kernel_store().unwrap(),
            &kernel_routes::ProjectBinding::new(&project),
            kernel::Surface::ExplicitSearch,
            None,
            kernel_routes::read::RowSelection::DomainDecisions("memory"),
        )
        .unwrap();
        assert!(memories.rows.is_empty());
        assert_eq!(state.starts.load(Ordering::SeqCst), 0);
    }

