    fn big_messages_from(start_ordinal: u64) -> Vec<IngressMessage> {
        (0..80)
            .map(|idx| {
                let ordinal = start_ordinal + idx;
                ck(
                    &format!("m{ordinal}"),
                    ordinal,
                    &format!("message {ordinal} {}", "word ".repeat(800)),
                )
            })
            .collect()
    }

    fn big_messages() -> Vec<IngressMessage> {
        big_messages_from(1)
    }

    fn zero_based_messages_with_system_lead() -> Vec<IngressMessage> {
        let mut messages = vec![wire_with_role("m0", 0, "system", "identity lead")];
        messages.extend((1..=80).map(|ordinal| {
            ck(
                &format!("m{ordinal}"),
                ordinal,
                &format!("message {ordinal} {}", "word ".repeat(800)),
            )
        }));
        messages
    }

    fn request_with_usage(
        messages: Vec<IngressMessage>,
        current_total_input_tokens: u64,
        context_limit_tokens: u64,
    ) -> Value {
        json!({
            "kind": "transform",
            "base_revision": "test-base",
            "v": 2,
            "serializer_profile": "owned-llmrunner",
            "session_id": "ses",
            "render_config": "cfg0",
            "usage": ModuleUsage {
                current_total_input_tokens,
                context_limit_tokens,
                ..ModuleUsage::default()
            },
            "messages": messages,
        })
    }

    fn request(messages: Vec<IngressMessage>) -> Value {
        request_with_usage(messages, 45_000, 50_000)
    }

    fn transform_request(
        messages: Vec<IngressMessage>,
        current_total_input_tokens: u64,
        context_limit_tokens: u64,
    ) -> TransformRequest {
        serde_json::from_value(request_with_usage(
            messages,
            current_total_input_tokens,
            context_limit_tokens,
        ))
        .unwrap()
    }

    async fn call_transform_request(handler: &Handler, request: Value) -> Value {
        call_transform_request_on_channel(handler, 7, request).await
    }

    /// Number of wire `keep` operations that address the named source.
    fn keeps_from(response: &Value, source: &str) -> usize {
        response["operations"]
            .as_array()
            .map(|operations| {
                operations
                    .iter()
                    .filter(|op| op["op"] == "keep" && op["source"] == source)
                    .count()
            })
            .unwrap_or_default()
    }

    async fn call_transform_request_on_channel(
        handler: &Handler,
        channel: u16,
        request: Value,
    ) -> Value {
        match handler
            .handle_transform_applied_for_test(test_route(channel), request)
            .await
        {
            PreparedOutcome::Response(bytes) => serde_json::from_slice(&bytes).unwrap(),
            other => panic!("unexpected handler outcome: {other:?}"),
        }
    }

    async fn call_transform_outcome(handler: &Handler, request: Value) -> PreparedOutcome {
        handler
            .handle_transform_applied_for_test(test_route(7), request)
            .await
    }

    async fn call_dispatch_request(handler: &Handler, request: Value) -> Value {
        call_dispatch_request_on_channel(handler, 7, request).await
    }

    async fn call_dispatch_request_on_channel(
        handler: &Handler,
        channel: u16,
        request: Value,
    ) -> Value {
        match handler.dispatch_value(test_route(channel), request).await {
            PreparedOutcome::Response(bytes) => serde_json::from_slice(&bytes).unwrap(),
            other => panic!("unexpected handler outcome: {other:?}"),
        }
    }

    fn error_frame(outcome: PreparedOutcome) -> (String, String) {
        match outcome {
            PreparedOutcome::Error { code, message } => (code, message),
            other => panic!("expected error outcome, got {other:?}"),
        }
    }

    fn error_code(outcome: PreparedOutcome) -> String {
        error_frame(outcome).0
    }

    async fn call_facade(handler: &Handler, name: &str, arguments: Value) -> PreparedOutcome {
        call_facade_on_channel(handler, 7, name, arguments).await
    }

    async fn call_facade_on_channel(
        handler: &Handler,
        channel: u16,
        name: &str,
        arguments: Value,
    ) -> PreparedOutcome {
        handler
            .dispatch_value(
                test_route(channel),
                json!({ "name": name, "arguments": arguments }),
            )
            .await
    }

    fn tool_body(outcome: PreparedOutcome) -> Value {
        match outcome {
            PreparedOutcome::Response(bytes) => serde_json::from_slice(&bytes).unwrap(),
            other => panic!("expected tool response, got {other:?}"),
        }
    }

    fn tool_is_error(outcome: PreparedOutcome) -> bool {
        tool_body(outcome)["isError"].as_bool().unwrap_or(false)
    }

    fn tool_text(outcome: PreparedOutcome) -> String {
        tool_body(outcome)["content"][0]["text"]
            .as_str()
            .unwrap()
            .to_string()
    }

    fn activate_module_authority(
        store: &MemoryStore,
        context_store_uuid: &str,
        identity: &str,
        route_project_root: &str,
        domain: &str,
    ) {
        let preparing = store
            .authority_begin_prepare(context_store_uuid, identity, domain)
            .unwrap();
        let checksum = store
            .authority_seed_checksum(context_store_uuid, identity, domain)
            .unwrap();
        store
            .authority_verify_prepare(
                context_store_uuid,
                identity,
                domain,
                preparing.generation,
                &checksum,
                &checksum,
            )
            .unwrap();
        let module = store
            .authority_ack_prepare(context_store_uuid, identity, domain, preparing.generation)
            .unwrap();
        assert_eq!(module.state, "MODULE");
        store
            .bind_authority_route(context_store_uuid, identity, route_project_root)
            .unwrap();
    }

    fn synthetic_text(response: &Value, index: usize) -> String {
        response["messages"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|message| message["meta"]["synthetic"] == json!(true))
            .nth(index)
            .and_then(|message| message["content"][0]["kind"]["text"].as_str())
            .unwrap_or_default()
            .to_string()
    }

    async fn call_transform(handler: &Handler, messages: Vec<IngressMessage>) -> Value {
        call_transform_request(handler, request(messages)).await
    }

    #[tokio::test(flavor = "current_thread")]
    async fn claude_code_response_cache_ttl_follows_model_config_and_is_omitted_without_one() {
        type Case<'a> = (fn(&mut DaemonConfig), Option<&'a str>, Option<&'a str>);
        let cases: [Case<'_>; 2] = [
            (
                |config| {
                    config
                        .cache_ttl_by_model
                        .insert("anthropic/claude-opus-4-1".to_string(), "300m".to_string());
                },
                Some("anthropic/claude-opus-4-1"),
                Some("1h"),
            ),
            (|config| config.cache_ttl = "90m".to_string(), None, None),
        ];
        for (configure, model_key, expected_cache_ttl) in cases {
            let mut config = default_test_config();
            config.model_chain.clear();
            configure(&mut config);
            let route_config = config.clone();
            let (handler, _store, _dir, project) =
                handler_with_store(Arc::new(ProducerState::default()), config);
            let mut route = binding(project.to_str().unwrap(), "ses");
            route.config = route_config;
            handler.bind_route(test_route(7), route);
            let mut transform_request = request(vec![ck("a", 1, "alpha")]);
            transform_request["serializer_profile"] = json!("claude-code-anthropic");
            if let Some(model_key) = model_key {
                transform_request["model_key"] = json!(model_key);
            }

            let response = call_transform_request(&handler, transform_request).await;
            match expected_cache_ttl {
                Some(expected) => assert_eq!(response["cache_ttl"], expected, "{model_key:?}"),
                None => assert!(response.get("cache_ttl").is_none(), "{response}"),
            }
        }
    }

    #[test]
    fn cached_transform_response_writer_is_byte_identical_to_value_round_trip() {
        let response =
            transform::TransformResponse::passthrough(vec![ck("wire-byte-cache", 1, "hello").ck]);
        let expected =
            serde_json::to_vec(&serde_json::to_value(response.clone()).unwrap()).unwrap();
        let request = transform_request(vec![ck("wire-byte-cache", 1, "hello")], 1, 100);
        let PreparedOutcome::Response(actual) = respond_transform(
            &request,
            response,
            Some(RecipeInputs::Ck {
                output_revision: Revision::parse("out-1").unwrap(),
                previous: None,
                retain: None,
            }),
        ) else {
            panic!("cached transform response failed to encode");
        };
        let actual_value: Value = serde_json::from_slice(&actual).unwrap();
        let mut expected_value: Value = serde_json::from_slice(&expected).unwrap();
        expected_value["base_revision"] = json!(request.base_revision.as_ref().unwrap().as_str());
        expected_value["output_revision"] = json!("out-1");
        expected_value["operations"] =
            json!([{"op": "insert", "values": [request.messages[0].ck]}]);
        assert_eq!(actual_value, expected_value);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn module_status_memory_metrics_match_budget_accounting_and_falsy_semantics() {
        let (handler, _store, _dir, _project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let response = call_transform_request(
            &handler,
            request(vec![ck("metrics", 1, "holder metrics fixture")]),
        )
        .await;
        assert_eq!(response["status"], "ok");
        let lease = {
            let mut snapshots = handler
                .transform_snapshots
                .lock()
                .expect("transform snapshots mutex");
            match snapshots.get("ses") {
                TransformSnapshotLookup::Ready(lease) => lease,
                _ => panic!("expected a ready snapshot lease"),
            }
        };
        {
            let mut pages = handler
                .transform_pages
                .lock()
                .expect("transform page mutex");
            let staged = pages
                .stage(
                    "collecting-session",
                    "transform-1".to_string(),
                    1,
                    0,
                    2,
                    "digest-0".to_string(),
                    json!({"messages": []}),
                    123,
                    false,
                    456,
                    Instant::now(),
                )
                .unwrap();
            assert!(matches!(staged, TransformPageStageAction::Ack(1)));
            let applying = pages
                .stage(
                    "completed-session",
                    "completed".to_string(),
                    1,
                    0,
                    1,
                    "digest-final".to_string(),
                    json!({"messages": []}),
                    0,
                    true,
                    789,
                    Instant::now(),
                )
                .unwrap();
            assert!(matches!(applying, TransformPageStageAction::Apply { .. }));
            pages.finish_apply(
                "completed-session",
                "completed".to_string(),
                1,
                1,
                "digest-final".to_string(),
                String::new(),
                Some(PreparedOutput::cached_bytes(vec![0; 17])),
            );
        }

        // Another handler's shutdown can clear shared memos before this status snapshot.
        tail_hygiene::hygiene_memos().clear();
        let outcome = handler.handle_status_value(&json!({"method": "status"}));
        let PreparedOutcome::Response(bytes) = outcome else {
            panic!("module status did not respond: {outcome:?}");
        };
        let status: Value = serde_json::from_slice(&bytes).unwrap();
        let metrics = &status["memory_holders"];
        let snapshot_charge = {
            let snapshots = handler
                .transform_snapshots
                .lock()
                .expect("transform snapshots mutex");
            assert_eq!(metrics["snapshots"]["charged_bytes"], snapshots.ready_bytes);
            assert_eq!(metrics["snapshots"]["entry_count"], 1);
            assert_eq!(metrics["snapshots"]["in_flight_entry_count"], 0);
            let TransformSnapshot::Ready { retained_bytes, .. } =
                snapshots.entries.get("ses").unwrap()
            else {
                panic!("expected ready snapshot");
            };
            *retained_bytes
        };
        assert_eq!(
            metrics["snapshots"]["active_lease_charged_bytes"],
            snapshot_charge
        );
        assert_eq!(metrics["snapshots"]["active_lease_entry_count"], 1);
        assert_eq!(
            metrics["serialized_output"]["charged_bytes"],
            handler
                .serialized_outputs
                .lock()
                .expect("serialized output cache mutex")
                .metrics()
                .0
        );
        assert_eq!(metrics["native_attach"]["charged_bytes"], 0);
        assert_eq!(metrics["native_attach"]["entry_count"], 0);
        let hygiene_memo = &metrics["tail_hygiene_memo"];
        assert!(hygiene_memo["entry_count"].is_u64());
        let charged = hygiene_memo["charged_bytes"].as_u64().unwrap();
        assert!(charged > std::mem::size_of::<OnceLock<tail_hygiene::HygieneMemos>>() as u64);
        assert!(charged <= tail_hygiene::MEMO_RETAINED_BYTES_BOUND as u64);
        assert!(hygiene_memo["rejected_inserts"].is_u64());
        assert_eq!(metrics["page_coordinator"]["charged_bytes"], 123);
        assert_eq!(metrics["page_coordinator"]["entry_count"], 1);
        assert_eq!(metrics["page_coordinator"]["completed_response_bytes"], 17);
        assert_eq!(metrics["page_coordinator"]["completed_response_count"], 1);
        assert_eq!(metrics["page_coordinator"]["collector_active"], true);
        assert_eq!(metrics["page_coordinator"]["oldest_queued_at_ms"], 456);
        handler
            .transform_pages
            .lock()
            .expect("transform page mutex")
            .discard("collecting-session");
        let idle_pages = handler.memory_holder_metrics();
        assert_eq!(idle_pages["page_coordinator"]["collector_active"], false);
        assert_eq!(
            idle_pages["page_coordinator"]["oldest_queued_at_ms"],
            Value::Null
        );
        drop(lease);
    }

    #[test]
    fn transform_health_idle_is_ok_and_queue_age_is_null_until_something_is_queued() {
        let health = DispatchHealth::new();
        let report = health.report(10_000);
        assert_eq!(report.status, HealthStatus::Ok);
        let metrics = report.metrics.unwrap();
        assert_eq!(metrics["in_flight_count"], json!(0));
        assert_eq!(metrics["oldest_queued_age_ms"], Value::Null);

        health.oldest_queued_at_ms.store(100, Ordering::Relaxed);
        let report = health.report(250);
        let metrics = report.metrics.unwrap();
        assert_eq!(metrics["oldest_queued_age_ms"], json!(150));
        assert_eq!(metrics["queue_stale"], json!(false));
    }

    #[test]
    fn transform_health_wedge_reports_lane_and_structured_staleness() {
        let health = DispatchHealth::new();
        health
            .last_dispatch_started_at_ms
            .store(200_000, Ordering::Relaxed);
        health
            .last_dispatch_completed_at_ms
            .store(50_000, Ordering::Relaxed);
        health.in_flight_count.store(1, Ordering::Relaxed);

        let report = health.report(200_001);
        assert_eq!(report.status, HealthStatus::Degraded);
        assert!(
            report
                .detail
                .as_deref()
                .is_some_and(|detail| detail.contains("transform lane"))
        );
        let metrics = report.metrics.unwrap();
        assert_eq!(metrics["heartbeat_stale"], json!(true));
        assert_eq!(metrics["in_flight_count"], json!(1));
        assert_eq!(metrics["completion_lag_ms"], json!(150_000));
    }

    #[test]
    fn transform_health_normal_advance_is_ok_and_errors_still_advance() {
        let health = DispatchHealth::new();
        let ticket = TransformDispatchTicket::new(&health);
        ticket.accept();
        assert_eq!(health.in_flight_count.load(Ordering::Relaxed), 1);
        ticket.finish(false);

        let normal_report = health.report(now_ms().max(0) as u64);
        assert_eq!(normal_report.status, HealthStatus::Ok);
        assert_eq!(health.in_flight_count.load(Ordering::Relaxed), 0);
        assert_eq!(
            normal_report.metrics.as_ref().unwrap()["consecutive_error_count"],
            json!(0)
        );

        let error_ticket = TransformDispatchTicket::new(&health);
        error_ticket.accept();
        error_ticket.finish(true);
        let error_report = health.report(now_ms().max(0) as u64);
        assert_eq!(error_report.status, HealthStatus::Ok);
        assert_eq!(
            error_report.metrics.as_ref().unwrap()["consecutive_error_count"],
            json!(1)
        );
        assert!(
            error_report
                .detail
                .as_deref()
                .is_some_and(|detail| detail.contains("advancing but erroring"))
        );
    }

    #[test]
    fn transform_health_refusal_does_not_advance_a_stale_completion_heartbeat() {
        let health = DispatchHealth::new();
        health
            .last_dispatch_started_at_ms
            .store(200_000, Ordering::Relaxed);
        health
            .last_dispatch_completed_at_ms
            .store(50_000, Ordering::Relaxed);
        {
            // A refused item never calls `accept`, so dropping its ticket cannot make the refusal loop appear as completed transform work.
            let _refused = TransformDispatchTicket::new(&health);
        }

        let report = health.report(200_001);
        assert_eq!(report.status, HealthStatus::Degraded);
        assert_eq!(
            health.last_dispatch_completed_at_ms.load(Ordering::Relaxed),
            50_000
        );
    }

    #[test]
    fn transform_dispatch_panic_drop_guard_decrements_without_completion_stamp() {
        let health = DispatchHealth::new();
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let ticket = TransformDispatchTicket::new(&health);
            ticket.accept();
            panic!("simulated transform dispatch panic");
        }));
        assert!(result.is_err());
        assert_eq!(health.in_flight_count.load(Ordering::Relaxed), 0);
        assert_eq!(
            health.last_dispatch_completed_at_ms.load(Ordering::Relaxed),
            0
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn serve_native_false_is_response_byte_identical_for_all_profiles() {
        let producer = Arc::new(ProducerState::default());
        let (handler, _store, _dir, _project) = handler_with_store(producer, default_test_config());
        for profile in [
            "owned-llmrunner",
            "owned-model_execution",
            "claude-code-anthropic",
            "opencode-aisdk",
            "pi",
        ] {
            let session_id = format!(
                "{}serve-native-false",
                history_summarizer::HISTORY_SUMMARIZER_CHILD_SESSION_PREFIX
            );
            let mut absent = request(vec![ck("m1", 1, "hello")]);
            absent["session_id"] = json!(session_id);
            absent["serializer_profile"] = json!(profile);
            let mut explicit_false = absent.clone();
            explicit_false["serve_native"] = json!(false);
            let mut absent_response = call_transform_request(&handler, absent).await;
            let mut explicit_response = call_transform_request(&handler, explicit_false).await;
            // Every recomputation names a fresh output revision and may keep from the previous one.
            for response in [&mut absent_response, &mut explicit_response] {
                let object = response.as_object_mut().unwrap();
                object.remove("output_revision");
                object.remove("previous_output_revision");
                object.remove("operations");
            }
            assert_eq!(
                serde_json::to_vec(&absent_response).unwrap(),
                serde_json::to_vec(&explicit_response).unwrap(),
                "profile {profile} changed the response when serve_native=false"
            );
        }
    }

    /// `request_observed_to_handler` ends where the typed decode starts, on both lanes: a
    /// decode that began ten seconds ago does not add those seconds to the span.
    #[tokio::test(flavor = "current_thread")]
    async fn request_observed_to_handler_ends_before_the_typed_decode() {
        let (handler, _store, _dir, _project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let observed_at = now_ms() - 20_000;
        let mut body = request(vec![ck("m1", 1, "hello")]);
        body["request_observed_at_ms"] = json!(observed_at);
        let parsed: TransformRequest = serde_json::from_value(body).unwrap();
        let decode_started_at = Instant::now() - Duration::from_secs(10);
        let ticket = TransformDispatchTicket::new(&DISPATCH_HEALTH);
        let pool = TestPool::unbounded();
        let meter = ResidentMeter::new(&pool);
        let runner = transform_unit::DetachedRunner::default();
        let entry = PassEntry {
            core: &handler.core,
            route: test_route(7),
            probe: None,
            meter: &meter,
            runner: &runner,
        };
        let outcome = handler
            .handle_transform_typed(&entry, parsed, None, decode_started_at, &ticket)
            .await;
        ticket.finish(false);
        let PreparedOutcome::Response(bytes) = outcome else {
            panic!("unexpected handler outcome: {outcome:?}");
        };
        let response: Value = serde_json::from_slice(&bytes).unwrap();
        let span = response["timings"]["request_observed_to_handler"]
            .as_f64()
            .unwrap();
        assert!(
            (9_000.0..11_000.0).contains(&span),
            "request_observed_to_handler was {span} ms; the decode span of 10 s must not be \
             counted in it"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn non_native_transform_skips_post_transform_tag_query() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) = handler_with_store(producer, default_test_config());
        assert_eq!(store.tag_number_query_count_for_test(), 0);

        let response = call_transform_request(&handler, request(vec![ck("m1", 1, "hello")])).await;

        assert_eq!(response["status"], "ok");
        assert!(response["timings"]["trigger_ms"].is_number());
        assert_eq!(response["timings"]["trigger_tokenized_blocks"], 1);
        assert!(response["timings"]["post_attach"].is_number());
        assert!(
            response["timings"]["handler_total"]
                .as_f64()
                .unwrap_or_default()
                > 0.0
        );
        assert!(response["timings"]["request_observed_to_handler"].is_number());
        let warm = call_transform_request(&handler, request(vec![ck("m1", 1, "hello")])).await;
        assert_eq!(warm["timings"]["trigger_tokenized_blocks"], 0);
        assert_eq!(
            store.tag_number_query_count_for_test(),
            0,
            "non-native attachment must not touch the tag table"
        );
    }

