    #[tokio::test(flavor = "current_thread")]
    async fn transform_refuses_a_retired_tail_delta() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) = handler_with_store(producer, default_test_config());
        let mut request = request(vec![ck("m1", 1, "hello")]);
        request["tail_delta"] = json!({ "after": "fp", "replace_from": 1 });
        let outcome = call_transform_outcome(&handler, request.clone()).await;
        assert_eq!(error_code(outcome), "transform_tail_delta_retired");
        // The refusal commits no cache state and publishes no snapshot.
        assert!(!store.has_cache_state("ses").unwrap());
        assert!(
            !handler
                .transform_snapshots
                .lock()
                .unwrap()
                .entries
                .contains_key("ses")
        );
        // An explicit null is absence, not a delta.
        request["tail_delta"] = Value::Null;
        let response = call_transform_request(&handler, request).await;
        assert_eq!(response["status"], "ok", "{response}");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn lineage_descent_on_the_whole_array_forces_full_projection() {
        let target = "projection-lineage-target";
        let source = "projection-lineage-source";
        let (handler, store, _dir, project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        handler.bind_route(test_route(7), binding(project.to_str().unwrap(), target));
        handler.bind_route(test_route(8), binding(project.to_str().unwrap(), source));
        let source_messages = (1..=10)
            .map(|ordinal| {
                ck(
                    &format!("prior-{ordinal}"),
                    ordinal,
                    &format!("turn {ordinal}"),
                )
            })
            .collect::<Vec<_>>();
        let source_request = native_cache_request(source, source_messages, Vec::new());
        let source_response = call_transform_request_on_channel(
            &handler,
            8,
            serde_json::to_value(source_request).unwrap(),
        )
        .await;
        assert_eq!(source_response["status"], "ok", "{source_response}");
        store
            .append_history_segments(
                source,
                &[
                    stored_comp(1, 1, 3, "prior-3", "history one through three"),
                    stored_comp(2, 4, 6, "prior-6", "history four through six"),
                ],
            )
            .unwrap();
        let source_epoch = store.load(source).unwrap().meta.revert_epoch;
        let summary = "This session is being continued from a previous conversation.\n\nSummary:\nDurable summary alpha\n\nFull transcript: /tmp/session.jsonl";
        let compaction_user = IngressMessage {
            mid: "lineage-summary".to_string(),
            ordinal: 1,
            ck: WireMessage::from_parts(
                "user",
                vec![
                    WireBlock::bare(BlockKind::Text {
                        text: "<system-reminder>Today's date: 2026-08-10</system-reminder>"
                            .to_string(),
                    }),
                    WireBlock::bare(BlockKind::Text {
                        text: summary.to_string(),
                    }),
                ],
                None,
                ProviderExtras::new(),
                HarnessMeta {
                    harness_id: Some("lineage-summary".to_string()),
                    ..Default::default()
                },
            ),
        };
        let initial_messages = vec![
            compaction_user,
            wire_with_role("lineage-tail", 2, "assistant", "continued answer"),
        ];
        let configure_lineage = |request: &mut TransformRequest, subagent: bool| {
            request.lineage_switched = true;
            request.is_subagent = subagent;
            request.descent_edge_id = 101;
            request.prior_conversation_key = source.to_string();
            request.prior_epoch = source_epoch;
            request.new_epoch = source_epoch.saturating_add(1);
            request.constituents = vec![(
                source.to_string(),
                target.to_string(),
                source_epoch.saturating_add(1),
            )];
            request.compaction_observed = true;
        };
        let mut subagent = native_cache_request(target, initial_messages.clone(), Vec::new());
        configure_lineage(&mut subagent, true);
        let passthrough =
            call_transform_request(&handler, serde_json::to_value(subagent).unwrap()).await;
        assert_eq!(passthrough["status"], "ok", "{passthrough}");

        let mut descended_messages = initial_messages;
        descended_messages[1] =
            wire_with_role("lineage-tail", 2, "assistant", "continued answer changed");
        let mut descent = native_cache_request(target, descended_messages, Vec::new());
        configure_lineage(&mut descent, false);
        let descended =
            call_transform_request(&handler, serde_json::to_value(descent).unwrap()).await;
        assert_eq!(descended["status"], "ok", "{descended}");
        assert_eq!(descended["lineage_descent_disposition"], "descended");
        assert_eq!(descended["lineage_switch_consumed_id"], 101);
        assert_eq!(descended["timings"]["projection_projected_messages"], 2);
        assert!(store.load(target).unwrap().meta.descent_completed);
    }

    #[test]
    fn colliding_recipe_keys_do_not_reserialize_previous_output() {
        let previous: Vec<transform::ServedMessage> = (0..edit_recipe::MAX_CONFIRM_PROBES)
            .map(|_| {
                serde_json::from_value(
                    serde_json::to_value(WireMessage::synthetic_user_text("x".repeat(256 * 1024)))
                        .unwrap(),
                )
                .unwrap()
            })
            .collect();
        let served: transform::ServedMessage = serde_json::from_value(
            serde_json::to_value(WireMessage::synthetic_user_text("tail")).unwrap(),
        )
        .unwrap();
        let previous = recipe_keyed(previous.iter());
        let output = recipe_keyed(std::iter::repeat_n(&served, 32));
        let before = served_json::FINALIZATIONS.with(std::cell::Cell::get);
        let built = edit_recipe::build_operations(&output, &[], Some(&previous), |a, b| {
            a.canonical_bytes() == b.canonical_bytes()
        });
        assert_eq!(
            served_json::FINALIZATIONS.with(std::cell::Cell::get),
            before
        );
        assert!(
            matches!(&built.operations[..], [edit_recipe::Operation::Insert { values }] if values.len() == output.len())
        );
    }

    #[test]
    fn recipe_matching_compares_served_payload_fields() {
        let value = json!({
            "role": "assistant",
            "content": [{"kind": {"type": "text", "text": "hello"}, "custom": "A",
                "provider_extras": {"custom": {"value": "retained"}}}],
            "meta": {"harness_id": "m1"}
        });
        let served: transform::ServedMessage = serde_json::from_value(value.clone()).unwrap();
        let mut changed = value;
        changed["content"][0]["custom"] = json!("B");
        let same: transform::ServedMessage = serde_json::from_value(changed.clone()).unwrap();
        assert_eq!(served.canonical_bytes(), same.canonical_bytes());
        changed["content"][0]["provider_extras"]["custom"]["value"] = json!("changed");
        let different: transform::ServedMessage = serde_json::from_value(changed).unwrap();
        assert_ne!(served.canonical_bytes(), different.canonical_bytes());
    }

    #[tokio::test(flavor = "current_thread")]
    async fn wire_recipe_keeps_from_previous_only_when_the_request_applied_it() {
        let (handler, _store, _dir, _project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        let messages = vec![ck("m1", 1, "hello"), ck("m2", 2, "again")];
        let first = call_transform_request(&handler, request(messages.clone())).await;
        assert_eq!(first["status"], "ok", "{first}");
        let applied = first["output_revision"].as_str().unwrap().to_owned();

        let mut unapplied = request(messages.clone());
        unapplied["base_revision"] = json!("test-base-unapplied");
        let PreparedOutcome::Response(bytes) = handler
            .handle_transform_for_test(test_route(7), unapplied)
            .await
        else {
            panic!("a transform without a previous revision still answers");
        };
        let response: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(response["status"], "ok", "{response}");
        assert!(
            response.get("previous_output_revision").is_none(),
            "{response}"
        );
        assert_eq!(keeps_from(&response, "previous"), 0, "{response}");
        let retained = response["output_revision"].as_str().unwrap().to_owned();
        assert_ne!(retained, applied);

        // Naming the revision the daemon retained reopens the previous source.
        let mut applied_request = request(messages);
        applied_request["base_revision"] = json!("test-base-applied");
        applied_request["previous_output_revision"] = json!(retained);
        let PreparedOutcome::Response(bytes) = handler
            .handle_transform_for_test(test_route(7), applied_request)
            .await
        else {
            panic!("a transform naming the retained revision answers");
        };
        let response: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(response["previous_output_revision"], retained, "{response}");
        assert!(keeps_from(&response, "previous") > 0, "{response}");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn wire_recipe_insert_depth_is_bounded_after_ingress() {
        let (handler, _store, _dir, _project) =
            handler_with_store(Arc::new(ProducerState::default()), default_test_config());
        for depth in [120, 121] {
            let mut nested = Value::Null;
            for _ in 0..depth {
                nested = Value::Array(vec![nested]);
            }
            let mut input = request(vec![ck(
                "deep",
                1,
                "text with [brackets] and \\\"quotes\\\"",
            )]);
            input["session_id"] = json!(format!(
                "{}deep",
                history_summarizer::HISTORY_SUMMARIZER_CHILD_SESSION_PREFIX
            ));
            input["messages"][0]["ck"]["provider_extras"] = json!({"p": {"v": nested}});
            let encoded = serde_json::to_vec(&input).unwrap();
            assert!(serde_json::from_slice::<Value>(&encoded).is_ok());
            match handler
                .handle_transform_for_test(test_route(7), input)
                .await
            {
                PreparedOutcome::Response(output) => {
                    let response: Value = serde_json::from_slice(&output)
                        .expect("successful recipe must fit the default JSON depth limit");
                    edit_recipe::Recipe::from_json(&response).expect("recipe depth contract");
                    assert_eq!(depth, 120, "oversized literal must be refused");
                    assert_eq!(response["status"], "ok");
                }
                PreparedOutcome::Error { code, .. } => {
                    assert_eq!(depth, 121, "boundary literal must be accepted");
                    assert_eq!(code, "encode_failed");
                }
                _ => panic!("transform must have a unary outcome"),
            }
        }
    }

