    #[tokio::test(flavor = "current_thread")]
    async fn guidance_get_freezes_hashes_and_advances_only_on_busting_commit() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) = handler_with_store(producer, default_test_config());
        handler.guidance_dates.lock().unwrap().insert(
            "ses".to_string(),
            "Today's date: Fri Jan 01 2016".to_string(),
        );

        let first = call_dispatch_request(
            &handler,
            json!({ "kind": "guidance.get", "session_id": "ses", "tool_present": true }),
        )
        .await;
        let first_bytes = first["bytes"].as_str().unwrap().to_string();
        assert!(first_bytes.ends_with("Today's date: Fri Jan 01 2016"));
        assert_eq!(
            first["content_hash"],
            json!(sha256_hex(GUIDANCE_TEXT.as_bytes()))
        );
        assert_eq!(
            first["hash"],
            json!(sha256_hex(first_bytes.as_bytes())),
            "hash covers exact returned bytes"
        );
        let repeated = call_dispatch_request(
            &handler,
            json!({ "kind": "guidance.get", "session_id": "ses", "tool_present": true }),
        )
        .await;
        assert_eq!(repeated["bytes"], first["bytes"]);
        assert_eq!(repeated["hash"], first["hash"]);

        let still_frozen = call_dispatch_request(
            &handler,
            json!({ "kind": "guidance.get", "session_id": "ses", "tool_present": true }),
        )
        .await;
        assert_eq!(still_frozen["bytes"], first["bytes"]);

        handler.guidance_dates.lock().unwrap().insert(
            "ses".to_string(),
            "Today's date: Sat Jan 02 2016".to_string(),
        );
        let _ = call_transform(&handler, vec![ck("m1", 1, "hello")]).await;
        let advanced = call_dispatch_request(
            &handler,
            json!({ "kind": "guidance.get", "session_id": "ses", "tool_present": true }),
        )
        .await;
        assert!(
            advanced["bytes"]
                .as_str()
                .unwrap()
                .ends_with("Today's date: Sat Jan 02 2016")
        );
        assert_ne!(advanced["hash"], first["hash"]);
        assert_eq!(advanced["content_hash"], first["content_hash"]);

        handler.bind_route(test_route(8), binding("/tmp/other", "other"));
        handler.guidance_dates.lock().unwrap().insert(
            "other".to_string(),
            "Today's date: Sun Jan 03 2016".to_string(),
        );
        let other = match handler
            .dispatch_value(
                test_route(8),
                json!({ "kind": "guidance.get", "session_id": "other", "tool_present": true }),
            )
            .await
        {
            PreparedOutcome::Response(bytes) => serde_json::from_slice::<Value>(&bytes).unwrap(),
            other => panic!("unexpected outcome: {other:?}"),
        };
        assert_ne!(other["hash"], advanced["hash"]);
        assert_eq!(other["content_hash"], advanced["content_hash"]);
        assert!(store.load("other").unwrap().row_version.is_none());
    }

    fn activate_notes_module_authority_via_finish_prepare(
        store: &MemoryStore,
        route_root: &str,
    ) -> String {
        let identity = "git:notes-eval";
        let preparing = store
            .authority_begin_prepare("ctx-eval", identity, "notes")
            .unwrap();
        store
            .authority_finish_prepare(
                "ctx-eval",
                identity,
                "notes",
                preparing.generation,
                "hash",
                "hash",
                true,
            )
            .unwrap();
        store
            .bind_authority_route("ctx-eval", identity, route_root)
            .unwrap();
        identity.to_string()
    }

    async fn register_note_evaluator(
        handler: &Handler,
        channel: u16,
        instance: &str,
        wake_owned: bool,
    ) -> (i64, String) {
        let response = call_dispatch_request_on_channel(
            handler,
            channel,
            json!({
                "method": "note.evaluation.register",
                "v": 2,
                "evaluator_instance": instance,
                "protocol_version": "2.0",
                "policy_version": 0,
                "capacity": 2,
                "wake_owned": wake_owned,
            }),
        )
        .await;
        assert_eq!(response["ok"], json!(true));
        assert_eq!(response["lease_ms"], json!(120_000));
        assert_eq!(response["heartbeat_ms"], json!(60_000));
        (
            response["registration_generation"].as_i64().unwrap(),
            response["token"].as_str().unwrap().to_string(),
        )
    }

    fn note_evaluation_next_body(
        token: &str,
        generation: i64,
        instance: &str,
        acquisition_id: &str,
    ) -> Value {
        json!({
            "method": "note.evaluation.next",
            "v": 2,
            "token": token,
            "registration_generation": generation,
            "evaluator_instance": instance,
            "evaluator_slot": 0,
            "acquisition_id": acquisition_id,
            "wait_ms": 0,
        })
    }

    fn insert_conditioned_note(
        store: &MemoryStore,
        project: &str,
        route_root: &str,
        condition: &str,
        compile_status: Option<&str>,
    ) -> StoredNote {
        store
            .insert_project_note(NoteWriteInput {
                project_path: project,
                route_project_root: Some(route_root),
                session_id: Some("ses"),
                content: "conditioned note body",
                surface_condition: Some(condition),
                anchor_block_id: None,
                anchor_ordinal: None,
                compiled_provider: None,
                compiled_config: None,
                compiled_at: None,
                compile_status,
                now_ms: 1,
            })
            .unwrap()
    }

    #[tokio::test(flavor = "current_thread")]
    async fn evaluator_policy_version_leaves_room_for_the_heartbeat_increment() {
        let resolver = FakeSessionResolver::with(&[("ses", FakeResolve::Hit("ses".to_string()))]);
        let (handler, store, _dir, project) = handler_with_store_and_resolver(
            Arc::new(ProducerState::default()),
            default_test_config(),
            resolver,
        );
        activate_notes_module_authority_via_finish_prepare(&store, project.to_str().unwrap());
        let register = |policy_version: i64| {
            json!({
                "method": "note.evaluation.register",
                "v": 2,
                "evaluator_instance": "eval-a",
                "protocol_version": "2.0",
                "policy_version": policy_version,
                "capacity": 2,
                "wake_owned": false,
            })
        };

        let (code, message) = error_frame(
            handler
                .dispatch_value(test_route(7), register(i64::MAX))
                .await,
        );
        assert_eq!(code, "bad_request");
        assert!(message.contains("'policy_version'"), "{message}");

        // The largest accepted version advances exactly once, then a further policy flip is
        // refused instead of wrapping.
        let registered = call_dispatch_request(&handler, register(i64::MAX - 1)).await;
        assert_eq!(registered["ok"], json!(true), "{registered}");
        let heartbeat = |wake_owned: bool| {
            json!({
                "method": "note.evaluation.heartbeat",
                "v": 2,
                "token": registered["token"],
                "registration_generation": registered["registration_generation"],
                "evaluator_instance": "eval-a",
                "wake_owned": wake_owned,
            })
        };
        let advanced = call_dispatch_request(&handler, heartbeat(true)).await;
        assert_eq!(advanced["policy_version"], json!(i64::MAX));
        let (code, message) = error_frame(
            handler
                .dispatch_value(test_route(7), heartbeat(false))
                .await,
        );
        assert_eq!(code, "bad_request");
        assert!(message.contains("i64::MAX"), "{message}");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn conditional_note_writes_require_a_live_protocol_v2_registration() {
        let resolver = FakeSessionResolver::with(&[("ses", FakeResolve::Hit("ses".to_string()))]);
        let (handler, store, _dir, project) = handler_with_store_and_resolver(
            Arc::new(ProducerState::default()),
            default_test_config(),
            resolver,
        );
        let route_root = project.to_str().unwrap().to_string();
        let identity = activate_notes_module_authority_via_finish_prepare(&store, &route_root);

        let conditioned = json!({
            "action": "write",
            "content": "pending without evaluator",
            "surface_condition": "when evaluated",
        });
        let refused = call_facade(&handler, "eidnara_note", conditioned.clone()).await;
        assert!(tool_text(refused).contains("Conditional-note evaluation is unavailable"));
        let note_statuses = [
            "active",
            "pending",
            "ready",
            "surfacing",
            "surfaced",
            "dismissed",
        ];
        assert!(
            store
                .read_project_notes(&identity, Some("ses"), &note_statuses, 100, 0)
                .unwrap()
                .is_empty(),
            "refused conditioned write must not create a session note"
        );
        assert!(
            store
                .read_conditional_notes(&identity, &note_statuses, 100, 0)
                .unwrap()
                .is_empty(),
            "refused conditioned write must not create a smart note"
        );

        let plain = call_facade(
            &handler,
            "eidnara_note",
            json!({"action": "write", "content": "plain note is allowed"}),
        )
        .await;
        assert!(!tool_is_error(plain));

        let state_sync = handler
            .dispatch_value(
                test_route(7),
                json!({
                    "method": "state_sync",
                    "session_id": "ses",
                    "shadow_generation": 0,
                    "expected_shadow_seq": 0,
                    "acked_watermarks": {},
                    "note_evaluation_available": true,
                }),
            )
            .await;
        assert!(matches!(state_sync, PreparedOutcome::Response(_)));
        let still_refused = call_facade(&handler, "eidnara_note", conditioned.clone()).await;
        assert!(
            tool_text(still_refused).contains("Conditional-note evaluation is unavailable"),
            "state_sync must not open the conditioned-write gate"
        );

        let (generation, token) = register_note_evaluator(&handler, 7, "eval-a", false).await;
        let accepted = call_facade(&handler, "eidnara_note", conditioned.clone()).await;
        let accepted_text = tool_text(accepted);
        assert!(accepted_text.contains("Created conditional note"));
        let note_id: i64 = accepted_text
            .split('#')
            .nth(1)
            .map(|rest| {
                rest.chars()
                    .take_while(char::is_ascii_digit)
                    .collect::<String>()
            })
            .unwrap()
            .parse()
            .unwrap();

        let heartbeat = call_dispatch_request(
            &handler,
            json!({
                "method": "note.evaluation.heartbeat",
                "v": 2,
                "token": token,
                "registration_generation": generation,
                "evaluator_instance": "eval-a",
            }),
        )
        .await;
        assert_eq!(heartbeat["ok"], json!(true));

        let unregistered = call_dispatch_request(
            &handler,
            json!({
                "method": "note.evaluation.unregister",
                "v": 2,
                "token": token,
                "registration_generation": generation,
                "evaluator_instance": "eval-a",
            }),
        )
        .await;
        assert_eq!(unregistered["ok"], json!(true));
        let original = store
            .get_note_by_id(&identity, "ses", note_id)
            .unwrap()
            .unwrap();
        let refused_update = call_facade(
            &handler,
            "eidnara_note",
            json!({
                "action": "update",
                "note_id": note_id,
                "content": "changed without evaluator",
                "surface_condition": "when changed",
            }),
        )
        .await;
        assert!(tool_text(refused_update).contains("the note was not updated"));
        let unchanged = store
            .get_note_by_id(&identity, "ses", note_id)
            .unwrap()
            .unwrap();
        assert_eq!(unchanged.content, original.content);
        assert_eq!(unchanged.surface_condition, original.surface_condition);

        let refused_again = call_facade(&handler, "eidnara_note", conditioned.clone()).await;
        assert!(tool_text(refused_again).contains("Conditional-note evaluation is unavailable"));

        let dismissed = call_facade(
            &handler,
            "eidnara_note",
            json!({"action": "dismiss", "note_id": note_id}),
        )
        .await;
        assert!(
            !tool_is_error(dismissed),
            "dismissal must not require an evaluator"
        );
        let read = call_facade(&handler, "eidnara_note", json!({"action": "read"})).await;
        assert!(!tool_is_error(read));

        let (expired_generation, expired_token) =
            register_note_evaluator(&handler, 7, "eval-a", false).await;
        {
            let mut registrations = handler.note_evaluator_registrations.lock().unwrap();
            for entries in registrations.values_mut() {
                for entry in entries.iter_mut() {
                    entry.expires_at = 0;
                }
            }
        }
        let ttl_refused = call_facade(&handler, "eidnara_note", conditioned).await;
        assert!(tool_text(ttl_refused).contains("Conditional-note evaluation is unavailable"));
        let stale_heartbeat = handler
            .dispatch_value(
                test_route(7),
                json!({
                    "method": "note.evaluation.heartbeat",
                    "v": 2,
                    "token": expired_token,
                    "registration_generation": expired_generation,
                    "evaluator_instance": "eval-a",
                }),
            )
            .await;
        assert_eq!(error_code(stale_heartbeat), "registration_unknown");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn conditioned_write_replays_recorded_response_without_live_evaluator() {
        let resolver = FakeSessionResolver::with(&[("ses", FakeResolve::Hit("ses".to_string()))]);
        let (handler, store, _dir, project) = handler_with_store_and_resolver(
            Arc::new(ProducerState::default()),
            default_test_config(),
            resolver,
        );
        let route_root = project.to_str().unwrap().to_string();
        activate_notes_module_authority_via_finish_prepare(&store, &route_root);

        register_note_evaluator(&handler, 7, "eval-a", false).await;
        let conditioned = json!({
            "action": "write",
            "content": "conditioned write with a command id",
            "surface_condition": "when evaluated",
            "command_id": "cmd-conditioned-replay",
        });
        let created = call_facade(&handler, "eidnara_note", conditioned.clone()).await;
        assert!(tool_text(created).contains("Created conditional note"));

        // The retry models a caller that lost the response and resends after the evaluator lease lapses.
        {
            let mut registrations = handler.note_evaluator_registrations.lock().unwrap();
            for entries in registrations.values_mut() {
                for entry in entries.iter_mut() {
                    entry.expires_at = 0;
                }
            }
        }
        let replayed = call_facade(&handler, "eidnara_note", conditioned).await;
        let replayed_text = tool_text(replayed);
        assert!(
            replayed_text.contains("Created conditional note"),
            "a recorded response must replay past the liveness gate: {replayed_text}"
        );

        let fresh = call_facade(
            &handler,
            "eidnara_note",
            json!({
                "action": "write",
                "content": "fresh conditioned write",
                "surface_condition": "when evaluated",
                "command_id": "cmd-conditioned-fresh",
            }),
        )
        .await;
        assert!(tool_text(fresh).contains("Conditional-note evaluation is unavailable"));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn note_evaluator_registration_rejects_wrong_versions_and_stale_credentials() {
        let resolver = FakeSessionResolver::with(&[("ses", FakeResolve::Hit("ses".to_string()))]);
        let (handler, store, _dir, project) = handler_with_store_and_resolver(
            Arc::new(ProducerState::default()),
            default_test_config(),
            resolver,
        );
        let route_root = project.to_str().unwrap().to_string();
        let identity = activate_notes_module_authority_via_finish_prepare(&store, &route_root);
        insert_conditioned_note(&store, &identity, &route_root, "when evaluated", None);

        let v1 = handler
            .dispatch_value(
                test_route(7),
                json!({
                    "method": "note.evaluation.register",
                    "v": 2,
                    "evaluator_instance": "eval-a",
                    "protocol_version": "1.0",
                    "policy_version": 0,
                    "capacity": 1,
                    "wake_owned": false,
                }),
            )
            .await;
        assert_eq!(error_code(v1), "protocol_unsupported");

        let (stale_generation, stale_token) =
            register_note_evaluator(&handler, 7, "eval-a", false).await;
        let (generation, token) = register_note_evaluator(&handler, 7, "eval-a", false).await;
        assert!(generation > stale_generation);

        let mut positive_wait = note_evaluation_next_body(&token, generation, "eval-a", "acq-1");
        positive_wait["wait_ms"] = json!(50);
        let positive = handler.dispatch_value(test_route(7), positive_wait).await;
        assert_eq!(error_code(positive), "positive_wait_unsupported");

        let stale = handler
            .dispatch_value(
                test_route(7),
                note_evaluation_next_body(&stale_token, stale_generation, "eval-a", "acq-1"),
            )
            .await;
        assert_eq!(error_code(stale), "registration_unknown");

        handler.bind_route(test_route(9), binding(&route_root, "ses"));
        let wrong_channel = handler
            .dispatch_value(
                test_route(9),
                note_evaluation_next_body(&token, generation, "eval-a", "acq-1"),
            )
            .await;
        assert_eq!(error_code(wrong_channel), "registration_unknown");

        let unknown_field = handler
            .dispatch_value(
                test_route(7),
                json!({
                    "method": "note.evaluation.next",
                    "v": 2,
                    "token": token,
                    "registration_generation": generation,
                    "evaluator_instance": "eval-a",
                    "evaluator_slot": 0,
                    "acquisition_id": "acq-1",
                    "wait_ms": 0,
                    "note_id": 1,
                }),
            )
            .await;
        assert_eq!(error_code(unknown_field), "bad_request");

        // Rejected attempts leave no stored decision, so reusing the acquisition ID claims fresh work.
        let next = call_dispatch_request(
            &handler,
            note_evaluation_next_body(&token, generation, "eval-a", "acq-1"),
        )
        .await;
        assert_eq!(next["result"], "claim");
        assert_eq!(next["replayed"], json!(false));
    }

