    fn wrapup_messages(count: u64, words_per_message: usize) -> Vec<IngressMessage> {
        (1..=count)
            .map(|ordinal| {
                wire_with_role(
                    &format!("m{ordinal}"),
                    ordinal,
                    if ordinal % 2 == 0 {
                        "assistant"
                    } else {
                        "user"
                    },
                    &format!("message {ordinal} {}", "word ".repeat(words_per_message)),
                )
            })
            .collect()
    }

    fn cache_wrapup_messages(handler: &Handler, messages: Vec<IngressMessage>) {
        cache_wrapup_messages_for_session(handler, "ses", messages);
    }

    fn cache_wrapup_messages_with_limit(
        handler: &Handler,
        messages: Vec<IngressMessage>,
        context_limit_tokens: u64,
    ) {
        cache_wrapup_messages_for_session_with_limit(
            handler,
            "ses",
            messages,
            context_limit_tokens,
        );
    }

    fn cache_wrapup_messages_for_session(
        handler: &Handler,
        session_id: &str,
        messages: Vec<IngressMessage>,
    ) {
        cache_wrapup_messages_for_session_with_limit(handler, session_id, messages, 200_000);
    }

    fn cache_wrapup_messages_for_session_with_limit(
        handler: &Handler,
        session_id: &str,
        messages: Vec<IngressMessage>,
        context_limit_tokens: u64,
    ) {
        let mut parsed = transform_request(messages, 1, context_limit_tokens);
        parsed.session_id = session_id.to_string();
        parsed.serializer_profile = SerializerProfile::ClaudeCodeAnthropic.wire_id().to_string();
        let retained_bytes = serde_json::to_vec(&parsed).unwrap().len();
        let projection = crate::wire::project_messages(&parsed.messages).unwrap();
        let store = handler.store().unwrap();
        let loaded = store.load(session_id).unwrap();
        let mut meta = loaded.meta.clone();
        meta.block_identity_by_mid
            .extend(projection.identity_by_mid);
        let revert_epoch = meta.revert_epoch;
        if meta != loaded.meta {
            store
                .commit(session_id, loaded.row_version, &loaded.core, &meta)
                .unwrap();
        }
        let mut snapshots = handler
            .transform_snapshots
            .lock()
            .expect("transform snapshots mutex");
        let generation = snapshots.begin(session_id);
        snapshots.finish_ready(
            session_id,
            generation,
            Arc::new(parsed),
            revert_epoch,
            retained_bytes,
        );
    }

    #[derive(Debug, PartialEq, Eq)]
    struct HistorySummarizerAdditiveRows {
        history_segment_count: usize,
        max_history_segment_seq: i64,
        transcript_count: usize,
        max_transcript_seq: i64,
        publication_floor_ordinal: Option<u64>,
    }

    fn history_summarizer_additive_rows(
        store: &MemoryStore,
        session_id: &str,
        project_path: &Path,
    ) -> HistorySummarizerAdditiveRows {
        let history_segments = store.load_history_segments(session_id).unwrap();
        let transcripts = store
            .load_chunk_transcripts_for_range(session_id, 0, i64::MAX)
            .unwrap();
        let _ = project_path;
        HistorySummarizerAdditiveRows {
            history_segment_count: history_segments.len(),
            max_history_segment_seq: store.max_history_segment_seq(session_id).unwrap(),
            transcript_count: transcripts.len(),
            max_transcript_seq: transcripts
                .iter()
                .map(|transcript| transcript.history_segment_seq)
                .max()
                .unwrap_or(0),
            publication_floor_ordinal: store
                .load(session_id)
                .unwrap()
                .meta
                .publication_floor_ordinal,
        }
    }

