    fn history_summarizer_output_for_prompt(prompt: &str) -> String {
        let (start, end) = prompt_ordinal_range(prompt).unwrap_or((1, 3));
        history_summarizer_output(start, end, "autonomous summary")
    }

    fn history_summarizer_output(start: u64, end: u64, p1: &str) -> String {
        format!(
            r#"<output><history_segments><history_segment start="{start}" end="{end}" title="autonomous arc" episode_type="feature" importance="60"><p1>{p1}</p1><p2>short summary</p2><p3>arc</p3><p4 /></history_segment></history_segments><meta><messages_processed>{start}-{end}</messages_processed><unprocessed_from>{}</unprocessed_from></meta></output>"#,
            end + 1
        )
    }

    fn history_summarizer_output_with_fact(start: u64, end: u64, fact: &str) -> String {
        format!(
            r#"<output><history_segments><history_segment start="{start}" end="{end}" title="autonomous arc" episode_type="feature" importance="60"><p1>autonomous summary</p1><p2>short summary</p2><p3>arc</p3><p4 /></history_segment></history_segments><facts><PROJECT_RULES>* {fact}</PROJECT_RULES></facts><meta><messages_processed>{start}-{end}</messages_processed><unprocessed_from>{}</unprocessed_from></meta></output>"#,
            end + 1
        )
    }

    fn prompt_ordinal_range(prompt: &str) -> Option<(u64, u64)> {
        let mut ordinals = Vec::new();
        let bytes = prompt.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == b'[' {
                let mut j = i + 1;
                while j < bytes.len() && bytes[j].is_ascii_digit() {
                    j += 1;
                }
                if j > i + 1 {
                    if let Ok(value) = prompt[i + 1..j].parse::<u64>() {
                        ordinals.push(value);
                    }
                    if j < bytes.len() && bytes[j] == b'-' {
                        let mut k = j + 1;
                        while k < bytes.len() && bytes[k].is_ascii_digit() {
                            k += 1;
                        }
                        if k > j + 1
                            && let Ok(value) = prompt[j + 1..k].parse::<u64>()
                        {
                            ordinals.push(value);
                        }
                    }
                }
            }
            i += 1;
        }
        Some((*ordinals.iter().min()?, *ordinals.iter().max()?))
    }

    const TEST_WAIT_BUDGET: Duration = Duration::from_secs(10);
    const TEST_WAIT_POLL: Duration = Duration::from_millis(2);

    async fn wait_for_idle(store: &MemoryStore) {
        let deadline = std::time::Instant::now() + TEST_WAIT_BUDGET;
        while std::time::Instant::now() < deadline {
            if store.load("ses").unwrap().meta.history_summarizer.state
                == HistorySummarizerPhase::Idle
            {
                return;
            }
            tokio::time::sleep(TEST_WAIT_POLL).await;
        }
        panic!("history_summarizer did not return to idle");
    }

    /// `cache_state_scalar_runs` is one handle's lifetime run count, so a count read across
    /// an eviction undercounts; a test that pins the count requires this function to return
    /// zero.
    fn cache_state_scalar_select_evictions(store: &MemoryStore) -> u32 {
        store
            .statement_evictions()
            .into_iter()
            .filter(|(sql, _)| sql.contains("json_type(meta"))
            .map(|(_, evictions)| evictions)
            .sum()
    }

    async fn wait_for_count(value: &AtomicUsize, expected: usize) {
        let deadline = std::time::Instant::now() + TEST_WAIT_BUDGET;
        while std::time::Instant::now() < deadline {
            if value.load(Ordering::SeqCst) >= expected {
                return;
            }
            tokio::time::sleep(TEST_WAIT_POLL).await;
        }
        panic!("counter did not reach {expected}");
    }

    async fn wait_for_history_summarizer_state<F>(store: &MemoryStore, predicate: F)
    where
        F: Fn(&HistorySummarizerDurableState) -> bool,
    {
        let deadline = std::time::Instant::now() + TEST_WAIT_BUDGET;
        while std::time::Instant::now() < deadline {
            let state = store.load("ses").unwrap().meta.history_summarizer;
            if predicate(&state) {
                return;
            }
            tokio::time::sleep(TEST_WAIT_POLL).await;
        }
        panic!("history_summarizer state predicate did not become true");
    }

    fn m0_text(response: &Value) -> String {
        response["messages"]
            .as_array()
            .unwrap()
            .iter()
            .find(|message| message["meta"]["synthetic"] == json!(true))
            .and_then(|message| message["content"][0]["kind"]["text"].as_str())
            .unwrap_or_default()
            .to_string()
    }

    #[tokio::test(flavor = "current_thread")]
    async fn authority_transform_uses_request_history_budget_on_hard() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) =
            handler_with_store(Arc::clone(&producer), default_test_config());
        store
            .replace_history_segments(
                "ses",
                &[
                    stored_comp(1, 1, 40, "m40", &"OLD ".repeat(200)),
                    stored_comp(2, 41, 80, "m80", &"NEW ".repeat(200)),
                ],
            )
            .unwrap();
        let mut request = request(big_messages());
        request["history_budget_tokens"] = json!(300.0);

        let response = call_transform_request(&handler, request).await;
        assert_eq!(response["action"], "HARD");
        let m0 = m0_text(&response);
        assert!(
            m0.contains("NEW"),
            "newest history_segment remains at P1: {m0}"
        );
        assert!(
            !m0.contains("OLD"),
            "request budget must reach the HARD decay renderer: {m0}"
        );
        let status = tool_body(handler.handle_session_status_value(
            test_route(7),
            &json!({ "method": "session.status", "v": 1, "session_id": "ses" }),
        ));
        let history = decay_render::extract_m0_block(&m0, "session-history").unwrap();
        assert_eq!(
            status["history_segment_tokens"],
            json!(tokenizer::estimate_tokens(&history))
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn session_status_carries_the_firing_timeline_counters_and_the_publication_pending_age() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) =
            handler_with_store(Arc::clone(&producer), default_test_config());
        let status = || {
            tool_body(handler.handle_session_status_value(
                test_route(7),
                &json!({ "method": "session.status", "v": 1, "session_id": "ses" }),
            ))
        };
        call_transform(&handler, vec![ck("m1", 1, "hello")]).await;
        let before = status();
        assert_eq!(before["history_summarizer"]["recent_firings"], json!([]));
        assert_eq!(before["history_summarizer"]["counters"]["firings"], 0);

        let fired = call_transform(&handler, big_messages()).await;
        assert_eq!(fired["history_summarizer"]["fired"], true);
        wait_for_idle(&store).await;
        let after = status();
        let firing = &after["history_summarizer"]["recent_firings"][0];
        assert_eq!(firing["source"], "pressure_path");
        assert_eq!(firing["clock"], "daemon_wall_ms");
        assert_eq!(firing["outcome"]["kind"], "published");
        assert!(
            firing["published_at_ms"].as_i64().unwrap() >= firing["fired_at_ms"].as_i64().unwrap()
        );
        assert_eq!(after["history_summarizer"]["counters"]["published"], 1);
        // The publication stamped the pending start, so the unrendered segment has an age before any pass renders it.
        let stamped = store.load("ses").unwrap().meta.m1_pending_since_ms;
        assert_eq!(stamped, firing["published_at_ms"].as_i64());
        assert_eq!(after["pending_m1_delta"], true);
        assert!(after["pending_m1_age_ms"].as_i64().is_some());
        assert!(
            after["pass_trace"]["scheduler_history"]
                .as_array()
                .unwrap()
                .iter()
                .all(|entry| entry["action"].is_string())
        );
    }

    #[tokio::test(flavor = "current_thread")]
