    #[tokio::test]
    async fn session_delete_clears_durable_state_for_the_bound_lineage() {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, project) = handler_with_store(producer, default_test_config());
        let session_id = "ses-delete";
        handler.bind_route(
            test_route(7),
            binding(project.to_str().unwrap(), session_id),
        );
        store
            .commit(
                session_id,
                None,
                &CoreState::empty(),
                &ModuleMeta {
                    pending_channel2_directive: Some(memory_store::PendingChannel2Directive {
                        text: "frozen reminder".to_string(),
                        directive_id: "directive-id".to_string(),
                        armed_at_ms: 1,
                        arming_watermark: 1,
                    }),
                    channel2_pressure_latched: true,
                    channel2_arming_watermark: 1,
                    ..Default::default()
                },
            )
            .unwrap();
        store
            .seed_tags_for_test(
                session_id,
                &[TagMintInput {
                    block_id: "m1#0".to_string(),
                    kind: "message".to_string(),
                    token_count: 1,
                    source_bytes: b"one".to_vec(),
                }],
                1,
            )
            .unwrap();

        // A retained completed-page response would otherwise replay deleted conversation data.
        {
            let mut pages = handler
                .transform_pages
                .lock()
                .expect("transform page mutex");
            pages
                .stage(
                    session_id,
                    "t".to_string(),
                    1,
                    0,
                    1,
                    "d".to_string(),
                    json!({"messages": []}),
                    1,
                    true,
                    1,
                    Instant::now(),
                )
                .unwrap();
            pages.finish_apply(
                session_id,
                "t".to_string(),
                1,
                1,
                "d".to_string(),
                String::new(),
                Some(PreparedOutput::cached_bytes(vec![0; 8])),
            );
            assert!(pages.completed(session_id, "t").is_some());
        }
        handler
            .transform_snapshots
            .lock()
            .expect("transform snapshots mutex")
            .begin(session_id);

        let deleted = tool_body(
            handler
                .core
                .handle_session_delete_value(
                    test_route(7),
                    &json!({ "method": "session.delete", "v": 1, "session_id": session_id }),
                )
                .await,
        );
        assert_eq!(deleted["ok"], json!(true));
        assert!(deleted["deleted_rows"].as_u64().unwrap() >= 2);
        assert!(!store.has_cache_state(session_id).unwrap());
        assert!(
            handler
                .transform_pages
                .lock()
                .expect("transform page mutex")
                .completed(session_id, "t")
                .is_none(),
            "session.delete must drop the retained page response while the route stays bound"
        );
        assert!(matches!(
            handler
                .transform_snapshots
                .lock()
                .expect("transform snapshots mutex")
                .get(session_id),
            TransformSnapshotLookup::Missing
        ));
        assert!(store.load_tags_for_session(session_id).unwrap().is_empty());
        assert!(
            store
                .load(session_id)
                .unwrap()
                .meta
                .pending_channel2_directive
                .is_none()
        );
    }

