        assert_eq!(acknowledgement["isError"], json!(true));
        assert!(
            acknowledgement["content"][0]["text"]
                .as_str()
                .unwrap()
                .contains("Refused: no valid tags to queue. tags 1 not found")
        );
        assert!(store.load_pending_agent_drops("ses").unwrap().is_empty());

