    #[tokio::test(flavor = "current_thread")]
    async fn wrapup_budget_bounds_busy_join_without_double_drive() {
        let producer = Arc::new(ProducerState::default());
        producer.block_output.store(true, Ordering::SeqCst);
        let (handler, store, _dir, _project) =
            handler_with_store(Arc::clone(&producer), default_test_config());
        let messages = big_messages();
        let transformed = call_transform(&handler, messages).await;
        assert_eq!(transformed["history_summarizer"]["fired"], json!(true));
        wait_for_count(&producer.starts, 1).await;
        *handler
            .wrapup_operation_budget
            .lock()
            .expect("wrapup operation budget mutex") = Some(Duration::from_millis(40));

        let request = json!({
            "method": "session.wrapup",
            "v": 1,
            "session_id": "ses",
            "keep": 5,
            "command_id": "budget-retry"
        });
        let body = tool_body(handler.dispatch_value(test_route(7), request.clone()).await);
        assert_eq!(body["disposition"], json!("retryable"), "{body}");
        assert_eq!(body["reason"], json!("budget_exhausted"));
        assert!(
            store
                .load_wrapup_command("ses", "budget-retry")
                .unwrap()
                .is_none()
        );
        assert!(
            body["summary"]
                .as_str()
                .unwrap()
                .contains("wrapup request budget expired")
        );
        assert_eq!(producer.starts.load(Ordering::SeqCst), 1);

        producer.block_output.store(false, Ordering::SeqCst);
        producer.notify.notify_waiters();
        wait_for_idle(&store).await;
        *handler
            .wrapup_operation_budget
            .lock()
            .expect("wrapup operation budget mutex") = None;
        let retry = tool_body(handler.dispatch_value(test_route(7), request).await);
        assert!(matches!(
            retry["disposition"].as_str(),
            Some("completed" | "nothing_to_compact")
        ));
        assert!(
            store
                .load_wrapup_command("ses", "budget-retry")
                .unwrap()
                .is_some()
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn session_delete_cancels_a_live_history_summarizer_firing() {
        let producer = Arc::new(ProducerState::default());
        producer.block_output.store(true, Ordering::SeqCst);
        let (handler, store, _dir, _project) =
            handler_with_store(Arc::clone(&producer), default_test_config());
        let transformed = call_transform(&handler, big_messages()).await;
        assert_eq!(transformed["history_summarizer"]["fired"], json!(true));
        wait_for_count(&producer.starts, 1).await;
        assert!(
            handler
                .live_history_summarizer_sessions
                .lock()
                .unwrap()
                .contains_key("ses")
        );

        let deleted = tool_body(
            handler
                .core
                .handle_session_delete_value(
                    test_route(7),
                    &json!({ "method": "session.delete", "v": 1, "session_id": "ses" }),
                )
                .await,
        );
        assert_eq!(deleted["ok"], json!(true), "{deleted}");

        // The producer never unblocks, so the only way the live entry can clear is the
        // cancellation the delete requested.
        let deadline = std::time::Instant::now() + TEST_WAIT_BUDGET;
        loop {
            if !handler
                .live_history_summarizer_sessions
                .lock()
                .unwrap()
                .contains_key("ses")
            {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "session.delete must cancel the in-flight history_summarizer firing"
            );
            tokio::time::sleep(TEST_WAIT_POLL).await;
        }
        assert!(
            producer.block_output.load(Ordering::SeqCst),
            "the firing must have ended by cancellation, not by producer output"
        );
        assert_eq!(
            store.load("ses").unwrap().row_version,
            None,
            "a cancelled firing must not write state back for the deleted session"
        );
    }

