    /// The fixture sets `producer_harness: None` to exercise legacy-row compatibility.
    fn seed_awaiting(store: &MemoryStore, messages: &[IngressMessage]) {
        seed_awaiting_with_harness(store, messages, None);
    }

    /// The fixture seeds an `AwaitingProducer` row with `producer_harness: None` to reproduce persisted rows without that field.
    fn seed_awaiting_with_harness(
        store: &MemoryStore,
        messages: &[IngressMessage],
        producer_harness: Option<&str>,
    ) {
        let canonical_messages = transform_request(messages.to_vec(), 1, 200_000).messages;
        let projection = crate::wire::project_messages(&canonical_messages).unwrap();
        let chunk = history_summarizer_chunk::build_history_summarizer_chunk(
            &canonical_messages,
            &projection.blocks,
            1,
            DEFAULT_HISTORY_SUMMARIZER_CHUNK_TOKENS,
            4,
        );
        let fingerprint_items: Vec<_> = chunk.snapshot.iter().map(|item| item.as_item()).collect();
        let fingerprint = history_summarizer::compute_chunk_fingerprint(&fingerprint_items);
        let selected_range_identities = canonical_messages
            .iter()
            .filter(|message| !message.ck.meta.synthetic && (1..=3).contains(&message.ordinal))
            .map(
                |message| memory_store::HistorySummarizerSelectedMessageIdentity {
                    mid: message.mid.clone(),
                    block_identities: projection.identity_by_mid[&message.mid].clone(),
                },
            )
            .collect();
        let loaded = store.load("ses").unwrap();
        let mut meta = loaded.meta;
        meta.block_identity_by_mid
            .extend(projection.identity_by_mid);
        meta.history_summarizer = HistorySummarizerDurableState {
            state: HistorySummarizerPhase::AwaitingProducer,
            firing_seq: 1,
            chunk_range: Some(HistorySummarizerChunkRange {
                from_ordinal: 1,
                to_ordinal: 3,
            }),
            chunk_fingerprint: fingerprint,
            selected_range_identities,
            presented_token_budget: None,
            producer_session_id: Some("producer-session".to_string()),
            producer_run_id: Some("run-reattach".to_string()),
            producer_harness: producer_harness.map(str::to_owned),
            fired_at_ms: Some(1),
            expected_revert_epoch: 0,
            history_segment_set_generation: memory_store::HistorySegmentSetGeneration::default(),
            failure_backoff_at_ms: None,
            last_failure: None,
            last_no_fire: None,
            consecutive_publish_failures: 0,
            chunk_retry: None,
            memory_reviewer_nonadmission: Default::default(),
            memory_reviewer_reservation: None,
            recent_firings: Vec::new(),
            counters: Default::default(),
            pending_eligibility: None,
        };
        store
            .commit("ses", loaded.row_version, &loaded.core, &meta)
            .unwrap();
    }

    fn seed_history_summarizer_phase(store: &MemoryStore, phase: HistorySummarizerPhase) {
        let loaded = store.load("ses").unwrap();
        let mut meta = loaded.meta;
        let selected_range_identities = seeded_history_summarizer_identities();
        for selected in &selected_range_identities {
            meta.block_identity_by_mid
                .insert(selected.mid.clone(), selected.block_identities.clone());
        }
        meta.history_summarizer = HistorySummarizerDurableState {
            state: phase,
            firing_seq: 1,
            chunk_range: Some(HistorySummarizerChunkRange {
                from_ordinal: 1,
                to_ordinal: 3,
            }),
            chunk_fingerprint: "seeded-fingerprint".to_string(),
            selected_range_identities,
            presented_token_budget: None,
            producer_session_id: Some("producer-session".to_string()),
            producer_run_id: Some("run-stale".to_string()),
            producer_harness: None,
            fired_at_ms: Some(1),
            expected_revert_epoch: 0,
            history_segment_set_generation: memory_store::HistorySegmentSetGeneration::default(),
            failure_backoff_at_ms: None,
            last_failure: None,
            last_no_fire: None,
            consecutive_publish_failures: 0,
            chunk_retry: None,
            memory_reviewer_nonadmission: Default::default(),
            memory_reviewer_reservation: None,
            recent_firings: Vec::new(),
            counters: Default::default(),
            pending_eligibility: None,
        };
        store
            .commit("ses", loaded.row_version, &loaded.core, &meta)
            .unwrap();
    }

    fn seed_idle(store: &MemoryStore) {
        let loaded = store.load("ses").unwrap();
        let mut meta = loaded.meta;
        meta.history_summarizer = HistorySummarizerDurableState::default();
        store
            .commit("ses", loaded.row_version, &loaded.core, &meta)
            .unwrap();
    }

    fn seed_abandoned_idle(store: &MemoryStore, backoff_at_ms: i64, detail: &str) {
        let loaded = store.load("ses").unwrap();
        let fired = match history_summarizer::fire(
            &HistorySummarizerDurableState::default(),
            1,
            3,
            "seeded-fingerprint".to_string(),
            Vec::new(),
            0,
            memory_store::HistorySegmentSetGeneration::default(),
            1,
        )
        .unwrap()
        {
            history_summarizer::FireOutcome::Fired(state) => state,
            history_summarizer::FireOutcome::Busy(_) => unreachable!(),
        };
        let mut meta = loaded.meta;
        meta.history_summarizer = history_summarizer::abandon_with_detail(
            &fired,
            backoff_at_ms,
            Some(detail.to_string()),
            memory_store::summarizer_timeline::AbandonClass::ProducerFailed,
        );
        store
            .commit("ses", loaded.row_version, &loaded.core, &meta)
            .unwrap();
    }

    fn expire_history_summarizer_backoff(store: &MemoryStore) {
        let loaded = store.load("ses").unwrap();
        let mut meta = loaded.meta;
        meta.history_summarizer.failure_backoff_at_ms = Some(now_ms() - 1);
        store
            .commit("ses", loaded.row_version, &loaded.core, &meta)
            .unwrap();
    }

    async fn assert_seeded_phase_recovers_then_refires_after_backoff(
        phase: HistorySummarizerPhase,
    ) {
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) =
            handler_with_store(Arc::clone(&producer), default_test_config());
        let messages = big_messages();
        seed_history_summarizer_phase(&store, phase.clone());

        let recovering = call_transform(&handler, messages.clone()).await;
        assert_eq!(
            recovering["history_summarizer"]["state"],
            phase.as_str(),
            "{phase:?}"
        );
        assert_eq!(
            recovering["history_summarizer"]["no_fire"], "recovering",
            "{phase:?}"
        );
        wait_for_idle(&store).await;
        assert_eq!(producer.connects.load(Ordering::SeqCst), 0, "{phase:?}");
        assert_eq!(producer.starts.load(Ordering::SeqCst), 0, "{phase:?}");
        assert_eq!(producer.binds.load(Ordering::SeqCst), 0, "{phase:?}");
        assert_eq!(producer.statuses.load(Ordering::SeqCst), 0, "{phase:?}");

        let backed_off = call_transform(&handler, messages.clone()).await;
        assert_eq!(
            backed_off["history_summarizer"]["fired"], false,
            "{phase:?}"
        );
        assert_eq!(
            backed_off["history_summarizer"]["no_fire"], "backoff",
            "{phase:?}"
        );
        assert_eq!(producer.starts.load(Ordering::SeqCst), 0, "{phase:?}");

        expire_history_summarizer_backoff(&store);
        let fresh = call_transform(&handler, messages).await;
        assert_eq!(fresh["history_summarizer"]["fired"], true, "{phase:?}");
        wait_for_count(&producer.starts, 1).await;
        wait_for_idle(&store).await;
    }

    #[tokio::test(flavor = "current_thread")]
    async fn handler_seeded_non_idle_phases_recover_then_refire_after_backoff() {
        for phase in [
            HistorySummarizerPhase::Publishing,
            HistorySummarizerPhase::Firing,
            HistorySummarizerPhase::Validating,
        ] {
            assert_seeded_phase_recovers_then_refires_after_backoff(phase).await;
        }
    }

    /// Records a reservation and a retained publication for the seeded firing, as the live path leaves them when publication fails after the handoff.
    fn seed_retained_reservation(store: &MemoryStore) {
        let loaded = store.load("ses").unwrap();
        let reservation = memory_store::MemoryReviewerReservation {
            firing_seq: loaded.meta.history_summarizer.firing_seq,
            causal_identity: "c".repeat(64),
            candidate_id: "hs-ses-candidate".to_string(),
            payload_digest: "d".repeat(64),
            kernel_incarnation: "k".repeat(64),
            queue_deadline_ms: now_ms()
                + memory_store::memory_reviewer_jobs::MEMORY_REVIEWER_QUEUE_LIFETIME_MS,
        };
        store
            .record_memory_reviewer_reservation(
                "ses",
                loaded.row_version.unwrap(),
                &reservation,
                &memory_store::PendingPublication {
                    validated_json: serde_json::to_string(
                        &history_summarizer_validate::ValidatedChunk::default(),
                    )
                    .unwrap(),
                    aliases_json: serde_json::to_string(
                        &history_summarizer_citations::FrozenAliasTable::default(),
                    )
                    .unwrap(),
                    chunk_transcript: "U: retained".to_string(),
                    boundary_dates: BTreeMap::new(),
                    publication_floor_ordinal: 3,
                    collect_user_memory_candidates: false,
                    created_at_ms: now_ms(),
                },
            )
            .unwrap();
    }

    async fn wait_for_reattach_to_finish(handler: &Handler) {
        let deadline = std::time::Instant::now() + TEST_WAIT_BUDGET;
        while std::time::Instant::now() < deadline {
            if handler.reattaching_sessions.lock().unwrap().is_empty() {
                return;
            }
            tokio::time::sleep(TEST_WAIT_POLL).await;
        }
        panic!("the reattach did not finish");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn a_retained_reserved_firing_waits_out_its_backoff_before_the_next_reattach() {
        // The test route has no MODULE memories authority, so the reserved firing cannot be verified and every recovery pass retains it. Retaining must arm the backoff and the next transform must honor it instead of running the recovery again.
        let producer = Arc::new(ProducerState::default());
        let (handler, store, _dir, _project) =
            handler_with_store(Arc::clone(&producer), default_test_config());
        let messages = big_messages();
        seed_history_summarizer_phase(&store, HistorySummarizerPhase::Publishing);
        seed_retained_reservation(&store);

        let recovering = call_transform(&handler, messages.clone()).await;
        assert_eq!(recovering["history_summarizer"]["no_fire"], "recovering");
        wait_for_reattach_to_finish(&handler).await;
        let retained = store.load("ses").unwrap().meta.history_summarizer;
        assert_eq!(retained.state, HistorySummarizerPhase::Publishing);
        assert!(retained.memory_reviewer_reservation.is_some());
        assert!(
            retained.failure_backoff_at_ms.is_some(),
            "a retained pass arms the backoff"
        );

        let backed_off = call_transform(&handler, messages.clone()).await;
        assert_eq!(backed_off["history_summarizer"]["no_fire"], "backoff");
        assert!(handler.reattaching_sessions.lock().unwrap().is_empty());

        expire_history_summarizer_backoff(&store);
        let again = call_transform(&handler, messages).await;
        assert_eq!(again["history_summarizer"]["no_fire"], "recovering");
        wait_for_reattach_to_finish(&handler).await;
        assert_eq!(producer.connects.load(Ordering::SeqCst), 0);
        assert_eq!(producer.starts.load(Ordering::SeqCst), 0);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn stale_reattach_task_rechecks_idle_before_connecting() {
        let producer = Arc::new(ProducerState::default());
        producer
            .outputs
            .lock()
            .unwrap()
            .push_back(history_summarizer_output(1, 3, "stale reattach summary"));
        let (handler, store, _dir, _project) =
            handler_with_store(Arc::clone(&producer), default_test_config());
        let messages = big_messages();
        seed_awaiting(&store, &messages);

        let parsed = transform_request(messages, 1, 200_000);
        let projection = wire::project_messages(&parsed.messages).unwrap();
        let binding = handler.resolve_binding(test_route(7), "ses").unwrap();
        let generation = handler.transform_snapshots.lock().unwrap().begin("ses");
        assert_eq!(
            handler.maybe_spawn_reattach(
                Arc::clone(&store),
                &parsed,
                generation,
                &binding,
                &projection,
                now_ms(),
            ),
            Some("reattaching")
        );
        seed_idle(&store);
        handler.tasks.close();
        tokio::time::timeout(Duration::from_secs(10), handler.tasks.wait())
            .await
            .unwrap();

        let loaded = store.load("ses").unwrap();
        assert_eq!(
            loaded.meta.history_summarizer,
            HistorySummarizerDurableState::default()
        );
        assert_eq!(producer.connects.load(Ordering::SeqCst), 0);
        assert_eq!(producer.starts.load(Ordering::SeqCst), 0);
        assert_eq!(producer.binds.load(Ordering::SeqCst), 0);
        assert_eq!(producer.statuses.load(Ordering::SeqCst), 0);
        assert_eq!(producer.await_outputs.load(Ordering::SeqCst), 0);
    }

    #[derive(Clone, Copy)]
    enum ReattachGenerationCase {
        SupersededBeforeReattachSpawn,
        FinishedReadyWithSameGeneration,
    }

    async fn run_reattach_generation_case(
        case: ReattachGenerationCase,
    ) -> (
        HistorySummarizerAdditiveRows,
        HistorySummarizerAdditiveRows,
        HistorySummarizerDurableState,
        bool,
    ) {
        let producer = Arc::new(ProducerState::default());
        producer.block_output.store(true, Ordering::SeqCst);
        producer
            .outputs
            .lock()
            .unwrap()
            .push_back(history_summarizer_output_with_fact(
                1,
                3,
                "Reattached generation fact.",
            ));
        let (handler, store, _dir, project) =
            handler_with_store(Arc::clone(&producer), default_test_config());
        let messages = big_messages();
        seed_awaiting(&store, &messages);
        let before = history_summarizer_additive_rows(&store, "ses", &project);
        let hook_ran = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let hook_ran_for_hook = Arc::clone(&hook_ran);
        let snapshots = Arc::clone(&handler.transform_snapshots);
        let store_for_hook = Arc::clone(&store);
        let messages_for_hook = messages.clone();
        *handler
            .between_transform_and_prepare
            .lock()
            .expect("interleave hook mutex") = Some(Box::new(move || {
            hook_ran_for_hook.store(true, Ordering::SeqCst);
            let mut snapshots = snapshots.lock().expect("transform snapshots mutex");
            match case {
                ReattachGenerationCase::SupersededBeforeReattachSpawn => {
                    snapshots.begin("ses");
                }
                ReattachGenerationCase::FinishedReadyWithSameGeneration => {
                    // Publication accepts a completed cache record whose numeric version is unchanged.
                    let parsed = transform_request(messages_for_hook, 1, 200_000);
                    let retained_bytes = serde_json::to_vec(&parsed).unwrap().len();
                    let revert_epoch = store_for_hook.load("ses").unwrap().meta.revert_epoch;
                    snapshots.finish_ready(
                        "ses",
                        1,
                        Arc::new(parsed),
                        revert_epoch,
                        retained_bytes,
                    );
                    assert!(matches!(
                        snapshots.entries.get("ses"),
                        Some(TransformSnapshot::Ready { generation: 1, .. })
                    ));
                }
            }
        }));

        let response = call_transform(&handler, messages).await;
        assert_eq!(response["history_summarizer"]["no_fire"], "reattaching");
        wait_for_count(&producer.await_outputs, 1).await;
        producer.block_output.store(false, Ordering::SeqCst);
        producer.notify.notify_waiters();
        wait_for_idle(&store).await;

        let after = history_summarizer_additive_rows(&store, "ses", &project);
        let state = store.load("ses").unwrap().meta.history_summarizer;
        (before, after, state, hook_ran.load(Ordering::SeqCst))
    }

    #[tokio::test(flavor = "current_thread")]
    async fn reattach_snapshot_fence_rejects_pre_observation_supersession_and_accepts_ready() {
        let (stale_before, stale_after, stale_state, stale_hook_ran) =
            run_reattach_generation_case(ReattachGenerationCase::SupersededBeforeReattachSpawn)
                .await;
        assert!(stale_hook_ran, "the pre-reattach interleave hook must run");
        assert_eq!(stale_after, stale_before);
        assert_eq!(stale_state.state, HistorySummarizerPhase::Idle);
        assert_eq!(stale_state.failure_backoff_at_ms, None);
        assert_eq!(
            stale_state.last_failure.as_deref(),
            Some("publish rejected: transform snapshot state changed after reattach started")
        );

        let (control_before, control_after, control_state, control_hook_ran) =
            run_reattach_generation_case(ReattachGenerationCase::FinishedReadyWithSameGeneration)
                .await;
        assert!(
            control_hook_ran,
            "the same-generation control hook must run"
        );
        assert_ne!(control_after, control_before);
        assert_eq!(control_state.state, HistorySummarizerPhase::Idle);
    }

    /// `chunk_range` fixes the messages the producer saw. The reattach must rebuild that range without applying the live chunk budget, which can otherwise drop messages the model's segments cover and abandon a completed producer run.
    #[tokio::test(flavor = "current_thread")]
    async fn handler_reattach_rebuilds_the_frozen_range_regardless_of_the_live_budget() {
        let producer = Arc::new(ProducerState::default());
        producer
            .outputs
            .lock()
            .unwrap()
            .push_back(history_summarizer_output(
                1,
                3,
                "reattached under a smaller budget",
            ));
        // Three alternating-role messages of roughly 4k tokens each render as three blocks that fit the default budget that fired them and exceed the 8k floor a 32k context limit derives.
        let messages: Vec<IngressMessage> = (1..=3)
            .map(|ordinal| {
                wire_with_role(
                    &format!("m{ordinal}"),
                    ordinal,
                    if ordinal % 2 == 1 {
                        "user"
                    } else {
                        "assistant"
                    },
                    &format!("message {ordinal} {}", "word ".repeat(4_000)),
                )
            })
            .collect();
        let config = DaemonConfig {
            history_summarizer_context_limit_tokens: 32_000,
            ..default_test_config()
        };
        assert_eq!(
            derive_history_summarizer_chunk_tokens(config.history_summarizer_context_limit_tokens),
            crate::config::MIN_HISTORY_SUMMARIZER_CHUNK_TOKENS
        );
        let (handler, store, _dir, _project) = handler_with_store(Arc::clone(&producer), config);
        seed_awaiting(&store, &messages);

        let response = call_transform(&handler, messages).await;
        assert_eq!(response["history_summarizer"]["no_fire"], "reattaching");
        wait_for_idle(&store).await;

        let state = store.load("ses").unwrap().meta.history_summarizer;
        assert_eq!(state.last_failure, None, "{state:?}");
        assert_eq!(state.failure_backoff_at_ms, None);
        let history_segments = store.load_history_segments("ses").unwrap();
        assert_eq!(history_segments.len(), 1);
        assert_eq!(history_segments[0].end_message, 3);
    }

    /// A reattachment must use the retry budget; otherwise it restores aliases the live cut removed from an oversized message and can accept facts citing unseen bytes.
    #[tokio::test(flavor = "current_thread")]
    async fn handler_reattach_presents_a_shrunk_chunk_under_its_retry_budget() {
        let config = DaemonConfig {
            history_summarizer_context_limit_tokens: 32_000,
            ..default_test_config()
        };
        let configured_budget =
            derive_history_summarizer_chunk_tokens(config.history_summarizer_context_limit_tokens);
        let failures = history_summarizer_chunk::SHRINK_CHUNK_AFTER_FAILURES;
        let messages: Vec<IngressMessage> = (1..=3)
            .map(|ordinal| {
                let words = if ordinal == 1 { 6_000 } else { 10 };
                wire_with_role(
                    &format!("m{ordinal}"),
                    ordinal,
                    if ordinal % 2 == 1 {
                        "user"
                    } else {
                        "assistant"
                    },
                    &format!("message {ordinal} {}", "word ".repeat(words)),
                )
            })
            .collect();
        let canonical_messages = transform_request(messages.clone(), 1, 200_000).messages;
        let projection = crate::wire::project_messages(&canonical_messages).unwrap();
        // At `failures`, the frozen range contains only the oversized first message.
        let rebuild = || {
            history_summarizer_chunk::build_history_summarizer_chunk(
                &canonical_messages,
                &projection.blocks,
                1,
                usize::MAX,
                2,
            )
        };
        let mut at_configured_budget = rebuild();
        history_summarizer_chunk::presented_input(&mut at_configured_budget, configured_budget);
        assert_eq!(at_configured_budget.chunk.aliases.aliases.len(), 1);
        let mut at_retry_budget = rebuild();
        history_summarizer_chunk::presented_input(&mut at_retry_budget, configured_budget / 2);
        assert!(
            at_retry_budget.chunk.aliases.aliases.is_empty(),
            "the live firing withdrew the cut alias"
        );

        let producer = Arc::new(ProducerState::default());
        producer
            .outputs
            .lock()
            .unwrap()
            .push_back(history_summarizer_output_with_fact(
                1,
                1,
                "[s1:0-4] cites bytes past the presented cut",
            ));
        let (handler, store, _dir, _project) = handler_with_store(Arc::clone(&producer), config);
        let frozen = rebuild();
        let fingerprint_items: Vec<_> = frozen.snapshot.iter().map(|item| item.as_item()).collect();
        let loaded = store.load("ses").unwrap();
        let mut meta = loaded.meta;
        meta.block_identity_by_mid
            .extend(projection.identity_by_mid.clone());
        meta.history_summarizer = HistorySummarizerDurableState {
            state: HistorySummarizerPhase::AwaitingProducer,
            firing_seq: 1,
            chunk_range: Some(HistorySummarizerChunkRange {
                from_ordinal: 1,
                to_ordinal: 1,
            }),
            chunk_fingerprint: history_summarizer::compute_chunk_fingerprint(&fingerprint_items),
            selected_range_identities: vec![
                memory_store::HistorySummarizerSelectedMessageIdentity {
                    mid: "m1".to_string(),
                    block_identities: projection.identity_by_mid["m1"].clone(),
                },
            ],
            producer_session_id: Some("producer-session".to_string()),
            producer_run_id: Some("run-reattach".to_string()),
            fired_at_ms: Some(1),
            chunk_retry: Some(memory_store::HistorySummarizerChunkRetry {
                chunk_start: 1,
                chunk_end: 1,
                failures,
                model_chain: default_test_config().model_chain,
                token_budget: configured_budget,
            }),
            ..HistorySummarizerDurableState::default()
        };
        store
            .commit("ses", loaded.row_version, &loaded.core, &meta)
            .unwrap();

        let response = call_transform(&handler, messages).await;
        assert_eq!(response["history_summarizer"]["no_fire"], "reattaching");
        wait_for_idle(&store).await;

        let state = store.load("ses").unwrap().meta.history_summarizer;
        assert_eq!(state.last_failure, None, "{state:?}");
        assert_eq!(store.load_history_segments("ses").unwrap().len(), 1);
        assert_eq!(
            state
                .memory_reviewer_nonadmission
                .latest
                .map(|recorded| recorded.code),
            Some(
                memory_store::MemoryReviewerNonadmissionCode::FactSetRejected {
                    failure: memory_store::ExtractionFailure::UnknownAlias,
                }
            ),
            "{state:?}"
        );
    }

